import{ar as s,as as a,at as p,au as e}from"./app-CUiZF7NJ.js";const t={};function l(o,n){return e(),a("div",null,[...n[0]||(n[0]=[p(`<h1 id="四、时间线-timeline" tabindex="-1"><a class="header-anchor" href="#四、时间线-timeline"><span>四、时间线-Timeline</span></a></h1><h2 id="_4-1-属性" tabindex="-1"><a class="header-anchor" href="#_4-1-属性"><span>4.1 属性</span></a></h2><h3 id="_4-1-1-autoremovechildren" tabindex="-1"><a class="header-anchor" href="#_4-1-1-autoremovechildren"><span>4.1.1 .autoRemoveChildren</span></a></h3><p><code>autoRemoveChildren</code> 是 Timeline 实例的布尔配置项，用于控制<strong>时间轴完成后是否自动移除内部子动画（Tween/Timeline）</strong>，不属于全局 <code>gsap.config()</code>，是 Timeline 构造参数。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">autoRemoveChildren</span><span class="token operator">:</span> Boolean <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>在创建 Timeline 时传入；也可在实例创建后修改 <code>tl.autoRemoveChildren = true</code>。</p></li><li><p>配置项说明</p><ul><li><p>autoRemoveChildren</p><p>时间轴播放完成（且没有重复<code>repeat:0</code>）时，自动清理、移除所有子补间。</p><ul><li>默认值：<code>true</code></li><li><code>true</code>：时间轴完成后，子动画从时间轴上被移除，释放引用。子动画实例会被垃圾回收，后续无法再用 <code>tl.getChildren()</code> 获取。</li><li><code>false</code>：子动画保留在时间轴内，播放完成后依然存在，可以反复调用 <code>tl.restart()</code> 重播。</li></ul></li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 创建时间轴，关闭自动移除子动画</span></span>
<span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">  <span class="token literal-property property">autoRemoveChildren</span><span class="token operator">:</span> <span class="token boolean">false</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">300</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">play</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li><strong>作用对象：Timeline 实例</strong>，不是全局 GSAP 配置，不能写在 <code>gsap.config()</code>。</li><li>生效时机：<strong>时间轴完整播放结束（到达结束时间点）</strong>，暂停/反向播放不会触发移除。</li><li>repeat 影响：</li></ol><ul><li><code>repeat &gt; 0</code>：时间轴会循环，<code>autoRemoveChildren</code> 不会在单次循环结束时清理；只有所有循环全部结束才触发。</li><li><code>repeat:-1</code>（无限循环）：永远不会触发子动画移除。</li></ul><ol start="4"><li>常见场景</li></ol><ul><li>默认 <code>true</code>：一次性动画，播放完销毁子动画节省内存。</li><li>设置 <code>false</code>：需要反复 <code>restart()</code>、动态查询子动画、多次复用这条时间轴。</li></ul><ol start="5"><li>副作用：<code>autoRemoveChildren:true</code> 完成后调用 <code>tl.getChildren()</code> 返回空数组。</li></ol><blockquote><p>区分：<code>autoRemoveChildren</code> 只移除<strong>时间轴上的子动画引用</strong>，不会删除页面 DOM 元素。</p></blockquote></li></ol><h3 id="_4-1-2-data" tabindex="-1"><a class="header-anchor" href="#_4-1-2-data"><span>4.1.2 .data</span></a></h3><p><code>.data</code> 是 Timeline 实例上的<strong>实例属性</strong>，用于挂载任意自定义数据，初始化时会读取构造参数 <code>vars.data</code>。</p><blockquote><p>提示：GSAP 的 <code>data</code> 属性属于所有 Animation 实例（Tween / Timeline），用于业务自定义数据存储，GSAP 内部不会读取、修改该属性。</p></blockquote><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 创建 timeline 时，在 vars 传入 data，会自动赋值给 tl.data</span></span>
<span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">  <span class="token literal-property property">data</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">id</span><span class="token operator">:</span> <span class="token string">&quot;anim-01&quot;</span><span class="token punctuation">,</span> <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&quot;入场动画&quot;</span> <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 读取 .data 属性</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span>data<span class="token punctuation">.</span>id<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// anim-01</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 直接修改 .data 属性</span></span>
<span class="line">tl<span class="token punctuation">.</span>data<span class="token punctuation">.</span>status <span class="token operator">=</span> <span class="token string">&quot;playing&quot;</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span>data <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token literal-property property">id</span><span class="token operator">:</span> <span class="token string">&quot;anim-02&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span> <span class="token comment">// 整体覆盖</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>属性说明</p><ul><li><code>tl.data</code>：任意类型，默认值 <code>undefined</code>；创建时传入 <code>vars.data</code> 则初始化为对应值。</li><li>GSAP 内部完全不消费这个属性，仅作为开发者自定义数据容器。</li></ul><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 完整示例</span></span>
<span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line"><span class="token literal-property property">data</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">type</span><span class="token operator">:</span> <span class="token string">&quot;fade&quot;</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">opacity</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 在回调里读取 timeline.data</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">eventCallback</span><span class="token punctuation">(</span><span class="token string">&quot;onComplete&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span>data<span class="token punctuation">.</span>type<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span>data<span class="token punctuation">.</span>finished <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>要点</p><ul><li>是<strong>属性</strong>，不是方法，不要写 <code>tl.data()</code>。</li><li>数据挂载在 timeline 实例上，timeline 被 <code>kill()</code> 销毁后实例引用消失，data 一同释放。</li><li>区分：<code>vars.data</code> 是创建时的配置项；<code>.data</code> 是实例上的属性。</li></ul></li></ol><h3 id="_4-1-3-labels" tabindex="-1"><a class="header-anchor" href="#_4-1-3-labels"><span>4.1.3 .labels</span></a></h3><p><code>.labels</code> 是 Timeline 实例的只读属性，存储时间轴上所有标签（label）的键值映射对象，标签用于标记时间点，方便跳转到指定位置播放。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 获取全部标签映射</span></span>
<span class="line">tl<span class="token punctuation">.</span>labels<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 获取单个标签对应的时间值</span></span>
<span class="line">tl<span class="token punctuation">.</span>labels<span class="token punctuation">[</span><span class="token string">&quot;myLabel&quot;</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：<code>.labels</code> 是<strong>只读属性</strong>，不能直接赋值修改；新增/删除标签请使用 <code>.addLabel()</code>。</p></blockquote></li><li><p>属性说明</p><p>对象类型，<code>{ labelName: time }</code>，key 为标签名称，value 为标签对应的时间轴时间（单位：秒）。</p><ul><li>标签通过 <code>addLabel(name, time)</code> 或时间轴链式 <code>.add(&quot;labelName&quot;, time)</code> 添加。</li><li>时间值是相对于 Timeline 根起点的绝对时间。</li><li>只读：<code>tl.labels = {}</code> 不会生效。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">addLabel</span><span class="token punctuation">(</span><span class="token string">&quot;midPoint&quot;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span> <span class="token comment">// 在1秒位置添加标签 midPoint</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token string">&quot;midPoint&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 读取所有标签</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span>labels<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// { midPoint: 1 }</span></span>
<span class="line"><span class="token comment">// 读取指定标签时间</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span>labels<span class="token punctuation">.</span>midPoint<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 1</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 跳转到标签位置播放</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">play</span><span class="token punctuation">(</span><span class="token string">&quot;midPoint&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li><strong>作用域：仅 Timeline 实例拥有，Tween 没有 labels 属性</strong>。</li><li>动态更新：调用 <code>addLabel()</code> 新增标签后，<code>tl.labels</code> 对象会自动更新。</li><li>标签查找：可用来遍历所有时间标记，批量校验时间点。</li><li>区分： <ul><li><code>.labels</code>：读取标签集合；</li><li><code>.addLabel()</code>：新增标签；</li><li><code>.removeLabel()</code>：移除指定标签。</li></ul></li><li>注意：标签名称字符串区分大小写。</li></ol></li></ol><h3 id="_4-1-4-parent" tabindex="-1"><a class="header-anchor" href="#_4-1-4-parent"><span>4.1.4 .parent</span></a></h3><p><code>.parent</code> 是 Timeline 实例的只读属性，指向当前时间轴的父级时间轴；如果当前 Timeline 是根时间轴，<code>parent</code> 值为 <code>null</code>。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 获取父时间轴</span></span>
<span class="line">tl<span class="token punctuation">.</span>parent<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：<code>.parent</code> 为只读属性，不能直接赋值修改父子关系；嵌套时间轴请使用 <code>.add()</code> 或直接传入父时间轴。</p></blockquote></li><li><p>属性说明</p><p>类型：<code>Timeline|null</code></p><ul><li>当当前时间轴被 <code>add()</code> 添加到另一个 Timeline 时，<code>parent</code> 指向这个父 Timeline。</li><li>根时间轴（没有被添加到任何其他时间轴）：<code>parent = null</code>。</li><li>只读，无法手动赋值修改。</li><li>多层嵌套时，可以链式向上查找：<code>tl.parent.parent</code>。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 父时间轴</span></span>
<span class="line"><span class="token keyword">const</span> parentTl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 子时间轴</span></span>
<span class="line"><span class="token keyword">const</span> childTl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">parentTl<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span>childTl<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 将子时间轴加入父时间轴</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>childTl<span class="token punctuation">.</span>parent <span class="token operator">===</span> parentTl<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// true</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>parentTl<span class="token punctuation">.</span>parent<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// null，根时间轴</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li><strong>作用域：仅 Timeline 实例拥有，Tween 没有 parent 属性</strong>。</li><li>父子关系由 <code>.add()</code> 建立，不是创建实例时绑定。</li><li>常见用途：递归遍历时间轴树结构，向上查找根时间轴。</li><li>解除父子关系：调用 <code>.remove()</code> 将子时间轴从父级移除后，<code>childTl.parent</code> 会变为 <code>null</code>。</li><li>区分： <ul><li><code>.parent</code>：向上获取父 Timeline；</li><li><code>.getChildren()</code>：向下获取当前时间轴所有子补间/子时间轴。</li></ul></li></ol></li></ol><h3 id="_4-1-5-scrolltrigger" tabindex="-1"><a class="header-anchor" href="#_4-1-5-scrolltrigger"><span>4.1.5 .scrollTrigger</span></a></h3><p><code>.scrollTrigger</code> 是 Timeline 实例上的属性，指向绑定到该时间线的 ScrollTrigger 实例，仅在创建 timeline 时传入 <code>scrollTrigger</code> 配置才会存在。</p><blockquote><p>提示：GSAP 的 ScrollTrigger 是插件，使用前必须通过 <code>gsap.registerPlugin(ScrollTrigger)</code> 注册。</p></blockquote><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 创建带 scrollTrigger 的 timeline</span></span>
<span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">  <span class="token literal-property property">scrollTrigger</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">trigger</span><span class="token operator">:</span> <span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">start</span><span class="token operator">:</span> <span class="token string">&quot;top center&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">end</span><span class="token operator">:</span> <span class="token string">&quot;bottom center&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">scrub</span><span class="token operator">:</span> <span class="token boolean">true</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 读取 timeline 的 scrollTrigger 实例</span></span>
<span class="line"><span class="token keyword">const</span> st <span class="token operator">=</span> tl<span class="token punctuation">.</span>scrollTrigger<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>属性说明</p><ul><li><code>tl.scrollTrigger</code>：获取绑定在当前 timeline 的 ScrollTrigger 对象，可以调用 ScrollTrigger 的方法如 <code>.refresh()</code>、<code>.kill()</code>、<code>.getVelocity()</code> 等。</li><li>如果 timeline 创建时没有配置 scrollTrigger，则该属性为 <code>undefined</code>。</li></ul><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 示例：通过 timeline.scrollTrigger 调用 ScrollTrigger API</span></span>
<span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">  <span class="token literal-property property">scrollTrigger</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">trigger</span><span class="token operator">:</span> <span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">scrub</span><span class="token operator">:</span> <span class="token number">1</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">300</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 访问 scrollTrigger 实例</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span>scrollTrigger<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span>scrollTrigger<span class="token punctuation">.</span><span class="token function">refresh</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 刷新滚动触发器</span></span>
<span class="line"><span class="token comment">// tl.scrollTrigger.kill(); // 销毁触发器</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>要点</p><ul><li>只读引用，<strong>不能直接赋值</strong>替换 <code>scrollTrigger</code>，如需修改触发器配置，在创建时配置或者操作 ScrollTrigger 实例本身。</li><li>当 timeline 被 <code>kill()</code> 销毁时，关联的 scrollTrigger 不会自动销毁，需要单独 <code>tl.scrollTrigger.kill()</code>。</li><li>一个 timeline 只能绑定<strong>单个 ScrollTrigger</strong>。</li></ul></li></ol><h3 id="_4-1-6-smoothchildtiming" tabindex="-1"><a class="header-anchor" href="#_4-1-6-smoothchildtiming"><span>4.1.6 .smoothChildTiming</span></a></h3><p><code>smoothChildTiming</code> 是 Timeline 构造参数，同时也是 Timeline 实例可读写属性，用于控制子动画时间计算模式，对嵌套时间轴场景影响明显。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 创建时配置</span></span>
<span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">smoothChildTiming</span><span class="token operator">:</span> Boolean <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 实例创建后读写</span></span>
<span class="line">tl<span class="token punctuation">.</span>smoothChildTiming<span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span>smoothChildTiming <span class="token operator">=</span> Boolean<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>属性说明</p><ul><li>类型：<code>Boolean</code></li><li>默认值：<code>false</code></li><li><code>false</code>：子补间/子时间轴的时间位置<strong>固定不变</strong>。当父时间轴发生反向播放、时间跳转、动态修改子动画起始时间时，子动画的起始时间点保持原始值。适合大多数常规时序动画。</li><li><code>true</code>：启用平滑子时间计算。父时间轴反向、跳时间、动态调整时，GSAP 会自动重新计算子动画的时间位置，保持视觉上连续平滑过渡。适合嵌套时间轴、动态修改时间、来回拖拽播放头的场景（例如 ScrollTrigger）。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 开启平滑子时间计算</span></span>
<span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">  <span class="token literal-property property">smoothChildTiming</span><span class="token operator">:</span> <span class="token boolean">true</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span>smoothChildTiming<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// true</span></span>
<span class="line">tl<span class="token punctuation">.</span>smoothChildTiming <span class="token operator">=</span> <span class="token boolean">false</span><span class="token punctuation">;</span> <span class="token comment">// 运行时关闭</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li><strong>作用域：仅 Timeline 实例，Tween 没有该属性</strong>。</li><li>典型适用场景：ScrollTrigger、拖拽播放头、反复正反播放、动态增删子动画。</li><li>代价：开启后有微小性能开销；简单固定时序动画建议保持默认 <code>false</code>。</li><li>行为差异 <ul><li><code>false</code>：子动画时间锚点固定，跳转播放头时子动画可能出现“跳变”。</li><li><code>true</code>：播放头来回移动时，子动画时间会自动重映射，过渡更顺滑。</li></ul></li><li>注意：仅影响<strong>子动画时间计算逻辑</strong>，不会改变动画本身的 duration、ease。</li></ol></li></ol><h3 id="_4-1-7-vars" tabindex="-1"><a class="header-anchor" href="#_4-1-7-vars"><span>4.1.7 .vars</span></a></h3><p><code>.vars</code> 是 Timeline（以及 Tween）实例上的可读写属性，保存创建实例时传入的原始配置对象。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 创建时间轴时传入vars配置</span></span>
<span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">paused</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token literal-property property">autoRemoveChildren</span><span class="token operator">:</span> <span class="token boolean">false</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 读取原始配置对象</span></span>
<span class="line">tl<span class="token punctuation">.</span>vars<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 修改vars内属性（部分配置支持运行时修改）</span></span>
<span class="line">tl<span class="token punctuation">.</span>vars<span class="token punctuation">.</span>paused <span class="token operator">=</span> <span class="token boolean">false</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：<code>.vars</code> 是实例存储的原始配置对象，但<strong>并不是所有属性修改后都会自动生效</strong>。</p></blockquote></li><li><p>属性说明</p><ul><li>类型：<code>Object</code></li><li>保存实例初始化时传入的全部配置项，例如 <code>paused</code>、<code>repeat</code>、<code>autoRemoveChildren</code>、<code>smoothChildTiming</code> 等。</li><li>是创建 Timeline 时传入的对象引用，不是副本。</li><li>部分属性修改后实时生效；部分属性（如 <code>smoothChildTiming</code>）在实例创建后修改才会生效；<strong>有些配置一旦创建实例就无法变更</strong>。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">  <span class="token literal-property property">paused</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token literal-property property">repeat</span><span class="token operator">:</span> <span class="token number">2</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token literal-property property">autoRemoveChildren</span><span class="token operator">:</span> <span class="token boolean">false</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span>vars<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// { paused: true, repeat: 2, autoRemoveChildren: false }</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 读取单个配置</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span>vars<span class="token punctuation">.</span>repeat<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 2</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 修改支持运行时更新的参数</span></span>
<span class="line">tl<span class="token punctuation">.</span>vars<span class="token punctuation">.</span>repeat <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li><strong>作用域：Timeline / Tween 实例都拥有 vars 属性</strong>。</li><li>不要混淆： <ul><li><code>tl.vars</code>：实例构造配置（时间轴本身的设置，paused、repeat等）</li><li>子tween的vars：子动画的属性（x、y、duration等）</li></ul></li><li>限制：直接修改 <code>tl.vars</code> 里的配置，<strong>不是全部选项都能动态更新</strong>。例如时间轴创建后修改 <code>tl.vars.smoothChildTiming</code> 会生效，但部分底层配置修改无效。稳妥做法：优先使用实例提供的方法修改， 而不是直接改 <code>.vars</code>。</li><li>用途：运行时读取动画原始配置、批量复制动画配置，调试查看实例初始化参数。</li><li>注意：<code>.vars</code> 不会包含通过链式 <code>.to()</code> 添加的子动画配置，仅存储 Timeline 自身构造参数。</li></ol></li></ol><h2 id="_4-2-方法" tabindex="-1"><a class="header-anchor" href="#_4-2-方法"><span>4.2 方法</span></a></h2><h3 id="_4-2-1-add" tabindex="-1"><a class="header-anchor" href="#_4-2-1-add"><span>4.2.1 <code>.add()</code></span></a></h3><p><code>.add()</code> 是 Timeline 实例方法，用于向时间线内添加补间、子时间线、回调函数或标签，支持指定插入时间位置，是 Timeline 底层核心方法。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 添加动画/回调/标签</span></span>
<span class="line">timeline<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span>target<span class="token punctuation">,</span> position<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>target</code>：<code>Tween | Timeline | Function | string</code><ul><li>Tween / Timeline：添加子动画实例</li><li>Function：添加时间点回调函数</li><li>string：添加时间标签（label）</li></ul></li><li><code>position</code>【可选】：<code>number | string</code>，默认追加到时间线末尾；支持绝对秒数、相对位置 <code>&quot;+=1&quot;</code> / <code>&quot;-=0.5&quot;</code>、已有标签名作为插入锚点</li></ul></li><li>返回值：当前 Timeline 实例，支持链式调用</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 添加补间，追加末尾</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span>gsap<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 在1秒位置插入子动画</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span>gsap<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">100</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">0.5</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 相对位置插入，上一个动画结束后延迟0.3s</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span>gsap<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">opacity</span><span class="token operator">:</span> <span class="token number">0</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token string">&quot;+=0.3&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 添加回调函数</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;到达该时间点&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">0.8</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 添加时间标签</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token string">&quot;middlePoint&quot;</span><span class="token punctuation">,</span> <span class="token number">1.5</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ol><h3 id="_4-2-2-addlabel" tabindex="-1"><a class="header-anchor" href="#_4-2-2-addlabel"><span>4.2.2 .addLabel()</span></a></h3><p><code>.addLabel()</code> 是 Timeline 实例方法，用于在时间轴指定时间位置添加时间标签，方便后续跳转到该时间点。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 添加标签</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">addLabel</span><span class="token punctuation">(</span>labelName<span class="token punctuation">,</span> position<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：标签会存入 timeline 的 <code>.labels</code> 对象；也可以使用 <code>.add()</code> 传入字符串实现同样添加标签效果。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>labelName</code>：<code>string</code>，标签名称，不能重复；重复添加同名标签会覆盖原有时间位置。</li><li><code>position</code>【可选】：<code>number | string</code>，默认值 <code>&quot;+=0&quot;</code>；支持绝对秒数、相对位置、已有标签作为锚点。</li></ul></li><li>返回值：当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 在 1.5s 位置添加标签</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">addLabel</span><span class="token punctuation">(</span><span class="token string">&quot;mid&quot;</span><span class="token punctuation">,</span> <span class="token number">1.5</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 在上一个动画结束后延迟0.2s添加标签</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">addLabel</span><span class="token punctuation">(</span><span class="token string">&quot;endAnim&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;+=0.2&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 使用标签控制动画跳转</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">seek</span><span class="token punctuation">(</span><span class="token string">&quot;mid&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span>labels<span class="token punctuation">.</span>mid<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 1.5</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>标签仅为时间标记，不会产生动画，存储在 <code>tl.labels</code> 对象中。</li><li>重复名称标签会覆盖旧标签时间。</li><li>支持使用标签名作为 <code>.add()</code>、<code>.seek()</code>、<code>.play()</code> 等方法的位置参数。</li><li>移除标签：直接使用 <code>delete tl.labels.labelName</code>。</li><li>区分： <ul><li><code>.addLabel(name, pos)</code>：方法，新增标签；</li><li><code>.labels</code>：实例属性，读取全部标签键值对。</li></ul></li></ol></li></ol><h3 id="_4-2-3-addpause" tabindex="-1"><a class="header-anchor" href="#_4-2-3-addpause"><span>4.2.3 .addPause()</span></a></h3><p><code>.addPause()</code> 是 Timeline 实例方法，用于在时间轴指定时间位置插入暂停点，播放头运行到该位置时动画自动暂停。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 添加暂停点</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">addPause</span><span class="token punctuation">(</span>position<span class="token punctuation">,</span> callback<span class="token punctuation">,</span> params<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：暂停点本质是在指定时间注册暂停行为；继续播放需要调用 <code>.resume()</code>。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>position</code>【可选】：<code>number | string</code>，默认值 <code>&quot;+=0&quot;</code>；支持绝对秒数、相对位置、已有标签作为锚点。</li><li><code>callback</code>【可选】：<code>Function</code>，到达暂停点时触发的回调函数。</li><li><code>params</code>【可选】：<code>Array</code>，传递给回调函数的参数数组。</li></ul></li><li>返回值：当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 在 1s 位置添加暂停点</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">addPause</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;到达暂停点&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">play</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 播放头走到1秒处暂停，执行回调</span></span>
<span class="line"><span class="token comment">// tl.resume(); // 恢复继续播放</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>暂停点属于时间轴内的时间标记，播放头正向/反向播放经过该时间点都会触发暂停。</li><li>一个时间轴可以添加多个 <code>.addPause()</code>。</li><li>移除暂停点：使用 <code>.removePause()</code>，传入暂停所在位置或标签名。</li><li>区分： <ul><li><code>.addPause()</code>：在时间轴内嵌入暂停行为；</li><li><code>.pause()</code>：立即暂停当前正在播放的动画，不是时间轴上的标记点。</li></ul></li></ol></li></ol><h3 id="_4-2-4-call" tabindex="-1"><a class="header-anchor" href="#_4-2-4-call"><span>4.2.4 .call()</span></a></h3><p><code>.call()</code> 是 Timeline 实例方法，用于在时间轴指定时间位置插入回调函数，播放头到达该时间点时执行函数。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token function">tl</span><span class="token punctuation">.</span><span class="token function">call</span><span class="token punctuation">(</span>callback<span class="token punctuation">,</span> params<span class="token punctuation">,</span> position<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：<code>.call()</code> 底层基于 <code>.add()</code> 封装，本质是添加回调到时间线；回调执行不占用时间轴时长。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>callback</code>：<code>Function</code>，播放头到达指定时间点要执行的回调函数。</li><li><code>params</code>【可选】：<code>Array</code>，传递给回调函数的参数数组。</li><li><code>position</code>【可选】：<code>number | string</code>，默认值 <code>&quot;+=0&quot;</code>；支持绝对秒数、相对位置、已有标签作为锚点。</li></ul></li><li>返回值：当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token comment">// 在上一个动画结束后执行回调</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;box 移动完成&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token comment">// 在 2.5s 位置执行回调，并传入参数</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">msg</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>msg<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string">&quot;到达2.5秒&quot;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token number">2.5</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>回调函数执行<strong>不会占用时间</strong>，仅为时间轴上一个瞬时触发点。</li><li>正向播放、反向回退播放头经过该时间点，都会触发回调。</li><li>回调不会阻塞动画渲染，内部不要写耗时同步代码。</li><li>区分： <ul><li><code>.call()</code>：时间轴内嵌入回调，播放头到达时间点触发；</li><li><code>eventCallback(&quot;onComplete&quot;, fn)</code>：时间轴实例生命周期回调（整体动画完成才触发）。</li></ul></li></ol></li></ol><h3 id="_4-2-5-clear" tabindex="-1"><a class="header-anchor" href="#_4-2-5-clear"><span>4.2.5 .clear()</span></a></h3><p><code>.clear()</code> 是 Timeline 实例方法，用于清空当前时间轴内所有子动画、标签、暂停点、回调等内容，时间轴实例本身保留。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">clear</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：<code>.clear()</code> 只会清空子项，不会销毁 Timeline 实例；实例上的 vars、data、scrollTrigger、事件回调等属性仍然保留。</p></blockquote></li><li><p>属性说明</p><ul><li>参数：无</li><li>返回值：当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">data</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&quot;demo&quot;</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">addLabel</span><span class="token punctuation">(</span><span class="token string">&quot;mid&quot;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;callback&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">clear</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 此时 tl 内部所有子动画、标签、call 全部清空</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span>data<span class="token punctuation">.</span>name<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// demo，data 属性保留</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">opacity</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 可以继续添加新动画</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>仅清除时间轴内部子内容，<strong>不会销毁 timeline 实例本身</strong>。</li><li>被清除掉的子动画/子时间轴会被 kill。</li><li>实例自身配置、<code>.data</code>、事件回调、<code>.scrollTrigger</code> 不会被清除。</li><li>区分： <ul><li><code>.clear()</code>：清空内部所有子元素，实例保留，可继续复用；</li><li><code>.kill()</code>：销毁整个时间轴实例，停止动画，释放实例。</li></ul></li></ol></li></ol><h3 id="_4-2-6-currentlabel" tabindex="-1"><a class="header-anchor" href="#_4-2-6-currentlabel"><span>4.2.6 .currentLabel()</span></a></h3><p><code>.currentLabel()</code> 是 Timeline 实例方法，获取播放头当前所在位置对应的标签名称。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">currentLabel</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：返回当前播放头位置之前最近的标签；播放头在两个标签之间时，返回左侧临近标签。没有匹配标签返回 <code>null</code>。</p></blockquote></li><li><p>属性说明</p><ul><li>参数：无</li><li>返回值：<code>string | null</code>，当前命中的标签名，不存在则返回 null。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">addLabel</span><span class="token punctuation">(</span><span class="token string">&quot;start&quot;</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">addLabel</span><span class="token punctuation">(</span><span class="token string">&quot;middle&quot;</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">addLabel</span><span class="token punctuation">(</span><span class="token string">&quot;end&quot;</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">seek</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">currentLabel</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// &quot;start&quot;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">seek</span><span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">currentLabel</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// &quot;middle&quot;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">seek</span><span class="token punctuation">(</span><span class="token operator">-</span><span class="token number">0.5</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">currentLabel</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// null</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>标签匹配规则：取<strong>小于等于当前播放时间</strong>的最近标签。</li><li>播放头跳转到标签时间点，会命中该标签。</li><li>反向播放同样遵循该规则。</li><li>区分： <ul><li><code>.currentLabel()</code>：方法，读取播放头当前对应的标签；</li><li><code>.labels</code>：实例属性，存储全部标签与对应时间的键值对象。</li></ul></li></ol></li></ol><h3 id="_4-2-7-delay" tabindex="-1"><a class="header-anchor" href="#_4-2-7-delay"><span>4.2.7 .delay()</span></a></h3><p><code>.delay()</code> 是 Timeline 实例方法，用于读取或设置时间轴的延迟时长，控制动画开始前等待的秒数。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 获取当前 delay 值</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">delay</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 设置 delay 值</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">delay</span><span class="token punctuation">(</span>value<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：设置 delay 不会改变时间轴内部子动画的时间位置，仅控制整体动画何时开始播放。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>value</code>【可选】：<code>number</code>，单位秒。不传参数则为读取；传入数值则设置延迟。</li></ul></li><li>返回值：不传参返回当前 delay 数值；传入参数返回当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">delay</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">delay</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 读取：1</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">delay</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 修改延迟为2秒</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span><span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>delay 是<strong>动画整体启动延迟</strong>，不是时间轴内部的时间偏移。</li><li>动画已经开始播放后，修改 delay 不会产生任何效果。</li><li>负数 delay 允许动画播放头提前启动（跳过前面部分）。</li><li>区分： <ul><li><code>.delay()</code>：读写实例的启动延迟；</li><li><code>.duration()</code>：读写动画本身总时长，不含延迟。</li></ul></li></ol></li></ol><h3 id="_4-2-8-duration" tabindex="-1"><a class="header-anchor" href="#_4-2-8-duration"><span>4.2.8 .duration()</span></a></h3><p><code>.duration()</code> 是 Timeline 实例方法，用于读取或设置时间轴的持续时长（不包含 delay）。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 获取当前 duration 值</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">duration</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 设置 duration 值</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">duration</span><span class="token punctuation">(</span>value<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：设置 duration 会缩放时间轴内所有子动画的时间，以适配新的总时长；delay 不属于 duration 的一部分。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>value</code>【可选】：<code>number</code>，单位秒。不传参数则为读取；传入数值则设置总时长。</li></ul></li><li>返回值：不传参返回当前 duration 数值；传入参数返回当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">duration</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 读取：2</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">duration</span><span class="token punctuation">(</span><span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 将整体时长缩放为4秒，内部动画自动拉长</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">duration</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 4</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>duration 是时间轴本体动画时长，<strong>不包含 delay</strong>；<code>totalDuration()</code> 才是包含 delay 的总时长。</li><li>修改 duration 会对时间轴内所有子补间、子时间轴进行时间缩放。</li><li>若时间轴设置了 <code>repeat</code>，duration 指单次循环的时长。</li><li>区分： <ul><li><code>.duration()</code>：单次动画时长，不含延迟；</li><li><code>.totalDuration()</code>：包含 delay + repeat 的完整总时长。</li></ul></li></ol></li></ol><h3 id="_4-2-9-endtime" tabindex="-1"><a class="header-anchor" href="#_4-2-9-endtime"><span>4.2.9 .endTime()</span></a></h3><p><code>.endTime()</code> 是 Timeline 实例方法，获取时间轴的结束时间（相对于父时间轴）。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">endTime</span><span class="token punctuation">(</span>includeRepeats<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：默认不包含 repeat，返回单次播放的结束时间；该方法<strong>只读，不能传入数值修改</strong>。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>includeRepeats</code>【可选】：<code>boolean</code>，默认值 <code>false</code>。<code>true</code> 时包含重复次数计算最终结束时间。</li></ul></li><li>返回值：<code>number</code>，单位秒。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">{</span><span class="token literal-property property">repeat</span><span class="token operator">:</span> <span class="token number">2</span><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">endTime</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 2，单次结束时间</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">endTime</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 6，包含2次repeat：2 * (2+1)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>时间轴无父级时，endTime 等价于自身 duration；存在父时间轴时，返回在父时间轴上的结束点位。</li><li><code>includeRepeats: true</code> 会把 repeat、repeatDelay 一并纳入计算。</li><li>仅用于读取，不支持传数字设置结束时间。</li><li>区分： <ul><li><code>.endTime()</code>：在父时间轴坐标系下的结束时间；</li><li><code>.duration()</code>：时间轴自身单次时长；</li><li><code>.totalDuration()</code>：包含 delay / repeat / repeatDelay 的总时长。</li></ul></li></ol></li></ol><h3 id="_4-2-10-eventcallback" tabindex="-1"><a class="header-anchor" href="#_4-2-10-eventcallback"><span>4.2.10 .eventCallback()</span></a></h3><p><code>.eventCallback()</code> 是 Timeline 实例方法，用于读取、添加或移除时间轴生命周期事件回调。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 设置回调</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">eventCallback</span><span class="token punctuation">(</span>type<span class="token punctuation">,</span> callback<span class="token punctuation">,</span> params<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 读取已有回调</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">eventCallback</span><span class="token punctuation">(</span>type<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 移除回调</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">eventCallback</span><span class="token punctuation">(</span>type<span class="token punctuation">,</span> <span class="token keyword">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：支持的事件类型：<code>onStart</code>、<code>onUpdate</code>、<code>onComplete</code>、<code>onReverseComplete</code>、<code>onRepeat</code>；也可在创建 timeline 的 vars 中直接配置。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>type</code>：<code>string</code>，事件名称（<code>onStart</code> / <code>onUpdate</code> / <code>onComplete</code> / <code>onReverseComplete</code> / <code>onRepeat</code>）</li><li><code>callback</code>【可选】：<code>Function|null</code>，传入函数则绑定；传入 <code>null</code> 移除回调；不传则读取当前绑定函数</li><li><code>params</code>【可选】：<code>Array</code>，传递给回调函数的参数数组</li></ul></li><li>返回值：读取回调时返回绑定的函数；设置/移除回调时返回当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 设置 onComplete 回调</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">eventCallback</span><span class="token punctuation">(</span><span class="token string">&quot;onComplete&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">msg</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>msg<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string">&quot;动画播放完成&quot;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 读取回调函数</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">eventCallback</span><span class="token punctuation">(</span><span class="token string">&quot;onComplete&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 移除回调</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">eventCallback</span><span class="token punctuation">(</span><span class="token string">&quot;onComplete&quot;</span><span class="token punctuation">,</span> <span class="token keyword">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li><code>onUpdate</code> 在每一帧播放头更新时持续触发，注意性能开销。</li><li>回调绑定在时间轴实例上，调用 <code>.kill()</code> 会自动清除事件回调。</li><li>反向播放回到起点时触发 <code>onReverseComplete</code>，正向播放结束触发 <code>onComplete</code>。</li><li>区分： <ul><li><code>.eventCallback()</code>：实例方法动态增删生命周期回调；</li><li><code>.call()</code>：在时间轴<strong>特定时间点</strong>插入瞬时回调，属于时间轴内子项。</li></ul></li></ol></li></ol><h3 id="_4-2-11-from" tabindex="-1"><a class="header-anchor" href="#_4-2-11-from"><span>4.2.11 .from()</span></a></h3><p><code>.from()</code> 是 Timeline 实例方法，用于向时间轴添加<strong>from补间动画</strong>，定义动画起始状态，目标元素从该起始状态过渡到当前DOM样式状态。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">from</span><span class="token punctuation">(</span>target<span class="token punctuation">,</span> vars<span class="token punctuation">,</span> position<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：底层内部调用 <code>.add()</code> 来添加补间；<code>from()</code> 是从设置的属性值<strong>回到元素现有状态</strong>，和 <code>to()</code> 方向相反。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>target</code>：<code>string | HTMLElement | NodeList | Array</code>，动画目标元素/选择器字符串</li><li><code>vars</code>：<code>object</code>，动画配置对象（duration、ease、opacity、x 等属性）</li><li><code>position</code>【可选】：<code>number | string</code>，默认值 <code>&quot;+=0&quot;</code>；支持绝对秒数、相对位置、标签锚点，用来控制该补间插入时间轴的位置</li></ul></li><li>返回值：当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 元素从 x:300，opacity:0 过渡到页面原始状态</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">from</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">300</span><span class="token punctuation">,</span> <span class="token literal-property property">opacity</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">from</span><span class="token punctuation">(</span><span class="token string">&quot;.circle&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">opacity</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token string">&quot;-=0.5&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li><code>.from()</code> 动画起点是配置内属性，终点为元素当前渲染样式。</li><li>支持 <code>from()</code> 的变体 <code>.fromTo()</code>，同时自定义起点与终点。</li><li>position 参数控制动画插入时间轴的位置，实现动画重叠。</li><li>区分： <ul><li><code>.from()</code>：起始属性由代码定义，终点使用元素现有样式；</li><li><code>.to()</code>：起始使用元素现有样式，终点由代码定义；</li><li><code>.fromTo()</code>：同时手动指定起始属性与结束属性。</li></ul></li></ol></li></ol><h3 id="_4-2-12-fromto" tabindex="-1"><a class="header-anchor" href="#_4-2-12-fromto"><span>4.2.12 .fromTo()</span></a></h3><p><code>.fromTo()</code> 是 Timeline 实例方法，用于向时间轴添加 fromTo 补间动画，同时手动指定动画起始状态与结束状态。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">fromTo</span><span class="token punctuation">(</span>target<span class="token punctuation">,</span> fromVars<span class="token punctuation">,</span> toVars<span class="token punctuation">,</span> position<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：底层内部调用 <code>.add()</code> 添加补间；不会读取元素当前样式作为起点或终点，完全由 fromVars 和 toVars 控制。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>target</code>：<code>string | HTMLElement | NodeList | Array</code>，动画目标元素/选择器字符串</li><li><code>fromVars</code>：<code>object</code>，动画起始属性配置</li><li><code>toVars</code>：<code>object</code>，动画结束属性配置（duration、ease 等动画参数写在此对象）</li><li><code>position</code>【可选】：<code>number | string</code>，默认值 <code>&quot;+=0&quot;</code>；支持绝对秒数、相对位置、标签锚点，用来控制该补间插入时间轴的位置</li></ul></li><li>返回值：当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 元素从 x:0 opacity:0 过渡到 x:200 opacity:1</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">fromTo</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token literal-property property">opacity</span><span class="token operator">:</span> <span class="token number">0</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">opacity</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">.</span><span class="token function">fromTo</span><span class="token punctuation">(</span><span class="token string">&quot;.circle&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token literal-property property">scale</span><span class="token operator">:</span> <span class="token number">0.5</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">150</span><span class="token punctuation">,</span> <span class="token literal-property property">scale</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token string">&quot;-=0.5&quot;</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li><code>.fromTo()</code> 不会采样元素当前样式，起点终点都由开发者定义，样式控制更稳定。</li><li>动画时长、缓动函数等动画配置必须放在 <code>toVars</code> 对象内，<code>fromVars</code> 只写起始属性。</li><li>position 参数可设置重叠动画，支持绝对时间、相对偏移、标签位置。</li><li>区分： <ul><li><code>.fromTo()</code>：同时自定义起始、结束属性；</li><li><code>.from()</code>：自定义起始属性，终点取自元素现有样式；</li><li><code>.to()</code>：自定义结束属性，起点取自元素现有样式。</li></ul></li></ol></li></ol><h3 id="_4-2-13-getbyid" tabindex="-1"><a class="header-anchor" href="#_4-2-13-getbyid"><span>4.2.13 .getById()</span></a></h3><p><code>.getById()</code> 是 Timeline 实例方法，根据 id 查找当前时间轴内匹配的子动画（Tween / Timeline）。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">getById</span><span class="token punctuation">(</span>id<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：仅在当前 Timeline 的子项中搜索，不会递归深入嵌套子时间轴；id 在创建动画时通过 vars.id 指定。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>id</code>：<code>string</code>，要查找的动画唯一标识</li></ul></li><li>返回值：<code>Tween | Timeline | null</code>，找到则返回对应动画实例，找不到返回 <code>null</code></li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token literal-property property">id</span><span class="token operator">:</span> <span class="token string">&quot;boxAnim&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.circle&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token literal-property property">id</span><span class="token operator">:</span> <span class="token string">&quot;circleAnim&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> boxTween <span class="token operator">=</span> tl<span class="token punctuation">.</span><span class="token function">getById</span><span class="token punctuation">(</span><span class="token string">&quot;boxAnim&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>boxTween<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> notFound <span class="token operator">=</span> tl<span class="token punctuation">.</span><span class="token function">getById</span><span class="token punctuation">(</span><span class="token string">&quot;test&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>notFound<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// null</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>只搜索<strong>直接子级</strong>，不会递归遍历嵌套 timeline 内部的子动画。</li><li>id 在创建补间/时间轴时，在 vars 对象里配置。</li><li>匹配到第一个 id 相同的实例就返回。</li><li>区分： <ul><li><code>.getById()</code>：按 id 查找直接子动画；</li><li><code>.getChildren()</code>：获取所有直接子动画组成数组。</li></ul></li></ol></li></ol><h3 id="_4-2-14-getchildren" tabindex="-1"><a class="header-anchor" href="#_4-2-14-getchildren"><span>4.2.14 .getChildren()</span></a></h3><p><code>.getChildren()</code> 是 Timeline 实例方法，获取当前时间轴的直接子项集合，子项可以是 Tween、Timeline、回调等动画实例。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">getChildren</span><span class="token punctuation">(</span>nested<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：默认只返回直接子级；传入 nested=true 会递归取出所有嵌套层级的子动画。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>nested</code>【可选】：<code>boolean</code>，默认值 <code>false</code>。<code>false</code> 仅获取直接子项；<code>true</code> 递归遍历所有嵌套子时间轴，返回全部子动画。</li></ul></li><li>返回值：<code>Array&lt;Tween | Timeline | Callback&gt;</code>，子动画实例数组。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> subTl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">subTl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.circle&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">100</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span>subTl<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 获取直接子项</span></span>
<span class="line"><span class="token keyword">const</span> directChildren <span class="token operator">=</span> tl<span class="token punctuation">.</span><span class="token function">getChildren</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>directChildren<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 递归获取所有嵌套子项</span></span>
<span class="line"><span class="token keyword">const</span> allChildren <span class="token operator">=</span> tl<span class="token punctuation">.</span><span class="token function">getChildren</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>allChildren<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点 5. 返回的数组是<strong>快照</strong>，对子项数组增删不会影响原时间轴。 6. 包含添加的回调、标签暂停点等时间轴子项，不只是补间动画。 7. 常用于批量操作子动画，例如批量 kill、批量修改时间缩放。 8. 区分： - <code>.getChildren()</code>：获取子动画数组； - <code>.getById()</code>：按 id 查找单个直接子动画。</p></li></ol><h3 id="_4-2-15-gettweensof" tabindex="-1"><a class="header-anchor" href="#_4-2-15-gettweensof"><span>4.2.15 .getTweensOf()</span></a></h3><p><code>.getTweensOf()</code> 是 Timeline 实例方法，检索时间轴内作用于指定目标元素的所有补间（Tween）实例。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">getTweensOf</span><span class="token punctuation">(</span>target<span class="token punctuation">,</span> nested<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：默认仅查找当前时间轴直接子级；开启 nested 参数可递归遍历嵌套子 Timeline。仅返回 Tween，不会返回子 Timeline。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>target</code>：<code>string | HTMLElement | NodeList | Array</code>，目标元素或选择器</li><li><code>nested</code>【可选】：<code>boolean</code>，默认值 <code>false</code>。<code>false</code> 只查直接子项；<code>true</code> 递归遍历所有嵌套时间轴</li></ul></li><li>返回值：<code>Array&lt;Tween&gt;</code>，匹配的补间实例数组，无匹配则返回空数组</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">opacity</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> subTl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">subTl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">scale</span><span class="token operator">:</span> <span class="token number">1.2</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span>subTl<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 获取直接子级中 .box 的补间</span></span>
<span class="line"><span class="token keyword">const</span> boxTweens <span class="token operator">=</span> tl<span class="token punctuation">.</span><span class="token function">getTweensOf</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>boxTweens<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 递归嵌套时间轴，获取全部 .box 补间</span></span>
<span class="line"><span class="token keyword">const</span> allBoxTweens <span class="token operator">=</span> tl<span class="token punctuation">.</span><span class="token function">getTweensOf</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>allBoxTweens<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点 5. 只筛选 <strong>Tween</strong>，不会返回 Timeline、callback、label 等其他子项。 6. target 支持多个元素，可传入 DOM 数组、NodeList。 7. 常用于批量修改目标元素动画、获取目标的所有动画时长。 8. 区分： - <code>.getTweensOf()</code>：按目标元素筛选，只返回Tween； - <code>.getChildren()</code>：获取全部子项（Tween/Timeline/call等）。</p></li></ol><h3 id="_4-2-16-globaltime" tabindex="-1"><a class="header-anchor" href="#_4-2-16-globaltime"><span>4.2.16 .globalTime()</span></a></h3><p><code>.globalTime()</code> 是 Timeline 实例方法，读取该时间轴播放头对应的<strong>全局时间</strong>（相对于根ticker的绝对时间）。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">globalTime</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：该方法为只读，不可传入数值进行设置；全局时间不受当前时间轴的时间缩放、偏移影响。</p></blockquote></li><li><p>属性说明</p><ul><li>参数：无</li><li>返回值：<code>number</code>，单位秒，当前播放头对应的全局时间戳</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">timeScale</span><span class="token operator">:</span> <span class="token number">0.5</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">seek</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">time</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 1，timeline本地时间</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">globalTime</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 对应全局时间</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li><code>.time()</code> 是<strong>当前timeline本地时间</strong>，受 <code>timeScale</code>、嵌套偏移影响；<code>.globalTime()</code> 是全局基准时间。</li><li>多层嵌套时间轴场景下，不同子时间轴同一 globalTime 代表真实同一帧时刻。</li><li>适合多时间轴同步，判断多个动画是否处于真实同一时间点。</li><li>区分： <ul><li><code>.globalTime()</code>：全局基准时间，不受自身timeScale影响；</li><li><code>.time()</code>：时间轴本地播放时间，受timeScale、父级时间变换影响。</li></ul></li></ol></li></ol><h3 id="_4-2-17-invalidate" tabindex="-1"><a class="header-anchor" href="#_4-2-17-invalidate"><span>4.2.17 .invalidate()</span></a></h3><p><code>.invalidate()</code> 是 Timeline 实例方法，清空动画的初始缓存状态，强制在下一次渲染时重新读取元素起始属性。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">invalidate</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：GSAP 会缓存动画开始时元素的属性值；当 DOM 样式手动变更后，调用 invalidate() 清除缓存，重新采样。</p></blockquote></li><li><p>属性说明</p><ul><li>参数：无</li><li>返回值：当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 手动修改元素样式</span></span>
<span class="line">document<span class="token punctuation">.</span><span class="token function">querySelector</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span>style<span class="token punctuation">.</span>x <span class="token operator">=</span> <span class="token string">&quot;100px&quot;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 清除缓存，下次播放重新读取元素起始状态</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">invalidate</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">restart</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>清除该时间轴内所有子补间的初始值缓存，不修改时间轴结构、标签、回调。</li><li>当元素样式被 JS / CSS 手动改动，想要动画从新状态开始播放时使用。</li><li>不会重置播放头、pause、reverse 等播放状态。</li><li>区分： <ul><li><code>.invalidate()</code>：清除属性缓存，重新采样元素状态；</li><li><code>.restart()</code>：重置播放头到起点并播放，<strong>不会清除属性缓存</strong>。</li></ul></li></ol></li></ol><h3 id="_4-2-18-isactive" tabindex="-1"><a class="header-anchor" href="#_4-2-18-isactive"><span>4.2.18 .isActive()</span></a></h3><p><code>.isActive()</code> 是 Timeline 实例方法，判断当前时间轴是否处于<strong>活跃播放状态</strong>。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">isActive</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：只要时间轴正在被 ticker 更新（播放、暂停但播放头仍在有效区间、等待 delay / repeatDelay），都会判定为 active；仅完全结束或 kill 后返回 false。</p></blockquote></li><li><p>属性说明</p><ul><li>参数：无</li><li>返回值：<code>boolean</code>，<code>true</code> 代表活跃，<code>false</code> 代表非活跃</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">delay</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token literal-property property">repeat</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">play</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">isActive</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// true</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 动画全部播放完成后</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">isActive</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// false</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>处于 delay 等待阶段、repeatDelay 等待阶段，<code>isActive()</code> 同样返回 <code>true</code>。</li><li>调用 <code>.pause()</code> 暂停，但播放头还在动画时间范围内，仍然是 active。</li><li>动画播放完毕、调用 <code>.kill()</code> 销毁实例，返回 <code>false</code>。</li><li>区分： <ul><li><code>.isActive()</code>：是否被GSAP ticker追踪更新（含等待、暂停在动画区间内）；</li><li><code>.paused()</code>：读取是否处于暂停状态，只代表播放开关。</li></ul></li></ol></li></ol><h3 id="_4-2-19-iteration" tabindex="-1"><a class="header-anchor" href="#_4-2-19-iteration"><span>4.2.19 .iteration()</span></a></h3><p><code>.iteration()</code> 是 Timeline 实例方法，用于读取或设置当前循环次数索引。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 获取当前 iteration</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">iteration</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 设置 iteration</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">iteration</span><span class="token punctuation">(</span>value<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：iteration 从 0 开始计数；第一次播放为 0，第一次重复循环为 1，以此类推。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>value</code>【可选】：<code>number</code>，循环索引。不传参数为读取；传入数值则设置当前循环索引。</li></ul></li><li>返回值：不传参返回当前 iteration 数值；传入参数返回当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">repeat</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">play</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 读取当前循环索引</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">iteration</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 跳转到第1次重复循环</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">iteration</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>循环索引起始值为 0，代表第一次播放；repeat 次数为 N，则最大 iteration 为 N。</li><li>设置 iteration 会跳转播放头到对应循环片段，可配合 seek 使用。</li><li>仅在配置了 <code>repeat</code> 的时间轴才有意义；无 repeat 时固定为 0。</li><li>区分： <ul><li><code>.iteration()</code>：读写当前所在循环索引；</li><li><code>.repeat()</code>：读写总共要循环多少次。</li></ul></li></ol></li></ol><h3 id="_4-2-20-kill" tabindex="-1"><a class="header-anchor" href="#_4-2-20-kill"><span>4.2.20 .kill()</span></a></h3><p><code>.kill()</code> 是 Timeline 实例方法，销毁时间轴实例，停止动画并释放相关资源。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 销毁整个时间轴</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">kill</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 只销毁指定目标的动画</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">kill</span><span class="token punctuation">(</span>target<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：kill 之后时间轴不再被 ticker 追踪，内部子动画一并销毁；和 clear() 仅清空子项不同，kill 会废弃实例。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>target</code>【可选】：<code>string | HTMLElement | NodeList | Array</code>，指定要销毁动画的目标元素，不传则销毁整个时间轴。</li></ul></li><li>返回值：<code>null</code></li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.circle&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 销毁全部动画，整个时间轴失效</span></span>
<span class="line"><span class="token comment">// tl.kill();</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 仅销毁 .box 相关的补间，保留时间轴与其他子动画</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">kill</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>不传参调用 <code>kill()</code>，会销毁时间轴本身，内部所有子Tween、子Timeline全部被kill，事件回调一并清除。</li><li>传入target时，仅销毁时间轴内作用于该目标的补间，Timeline实例本身保留。</li><li>kill后的实例不要再调用play、seek等方法，行为不可预期。</li><li>区分： <ul><li><code>.kill()</code>：销毁实例/指定目标动画，释放资源；</li><li><code>.clear()</code>：清空内部子项，Timeline实例仍然可用。</li></ul></li></ol></li></ol><h3 id="_4-2-21-killtweensof" tabindex="-1"><a class="header-anchor" href="#_4-2-21-killtweensof"><span>4.2.21 .killTweensOf()</span></a></h3><p><code>.killTweensOf()</code> 是 Timeline 实例方法，销毁时间轴内作用于指定目标元素的所有补间动画。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">killTweensOf</span><span class="token punctuation">(</span>target<span class="token punctuation">,</span> nested<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：仅销毁Tween补间，不会销毁Timeline实例本身；默认只查找直接子级，可开启nested递归嵌套子时间轴。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>target</code>：<code>string | HTMLElement | NodeList | Array</code>，目标元素或选择器</li><li><code>nested</code>【可选】：<code>boolean</code>，默认值 <code>false</code>。<code>false</code> 仅查找直接子项；<code>true</code> 递归遍历所有嵌套子时间轴</li></ul></li><li>返回值：当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">opacity</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> subTl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">subTl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">scale</span><span class="token operator">:</span> <span class="token number">1.2</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span>subTl<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 销毁直接子项里 .box 的补间</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">killTweensOf</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 递归嵌套时间轴，销毁全部 .box 补间</span></span>
<span class="line"><span class="token comment">// tl.killTweensOf(&quot;.box&quot;, true);</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>只销毁目标对应的Tween，时间轴实例、标签、call回调、子Timeline容器本身保留。</li><li>销毁后的补间不再参与动画渲染，播放头仍可正常运行。</li><li>适合只清除某个元素动画，保留时间轴其他内容继续使用。</li><li>区分： <ul><li><code>.killTweensOf()</code>：仅杀死指定目标的Tween，Timeline实例保留；</li><li><code>.kill(target)</code>：效果近似，但<code>.kill()</code>不传参时直接销毁整个时间轴实例。</li></ul></li></ol></li></ol><h3 id="_4-2-22-nextlabel" tabindex="-1"><a class="header-anchor" href="#_4-2-22-nextlabel"><span>4.2.22 .nextLabel()</span></a></h3><p><code>.nextLabel()</code> 是 Timeline 实例方法，获取播放头当前位置之后<strong>最近的下一个标签名称</strong>。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">nextLabel</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：返回大于当前播放时间的最近标签；播放头在最后一个标签之后，返回 <code>null</code>。</p></blockquote></li><li><p>属性说明</p><ul><li>参数：无</li><li>返回值：<code>string | null</code>，下一个临近标签名，不存在则返回 null。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">addLabel</span><span class="token punctuation">(</span><span class="token string">&quot;start&quot;</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">addLabel</span><span class="token punctuation">(</span><span class="token string">&quot;middle&quot;</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">addLabel</span><span class="token punctuation">(</span><span class="token string">&quot;end&quot;</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">seek</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">nextLabel</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// &quot;middle&quot;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">seek</span><span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">nextLabel</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// &quot;end&quot;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">seek</span><span class="token punctuation">(</span><span class="token number">4.5</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">nextLabel</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// null</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>匹配规则：取<strong>大于当前播放头时间</strong>的最近标签。</li><li>反向播放时，依然按时间轴时间大小判断，不是播放方向。</li><li>常用于实现“跳转到下一章节”的交互逻辑。</li><li>区分： <ul><li><code>.nextLabel()</code>：获取播放头后方最近标签；</li><li><code>.currentLabel()</code>：获取播放头所在区间对应的标签；</li><li><code>.previousLabel()</code>：获取播放头前面最近的标签。</li></ul></li></ol></li></ol><h3 id="_4-2-23-pause" tabindex="-1"><a class="header-anchor" href="#_4-2-23-pause"><span>4.2.23 .pause()</span></a></h3><p><code>.pause()</code> 是 Timeline 实例方法，暂停时间轴播放，停止播放头继续前进。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">pause</span><span class="token punctuation">(</span>atTime<span class="token punctuation">,</span> suppressEvents<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：暂停会停留在当前播放位置；可以可选指定跳转时间再暂停，suppressEvents 控制是否屏蔽事件回调触发。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>atTime</code>【可选】：<code>number | string</code>，跳转至该时间/标签位置后暂停。</li><li><code>suppressEvents</code>【可选】：<code>boolean</code>，默认值 <code>false</code>。<code>true</code> 时跳转过程不触发 <code>onUpdate</code>、<code>onStart</code> 等事件回调。</li></ul></li><li>返回值：当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">play</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 在当前位置直接暂停</span></span>
<span class="line"><span class="token comment">// tl.pause();</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 跳转到1秒位置然后暂停，不触发事件</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">pause</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>暂停后实例仍然保持 active 状态，调用 <code>.resume()</code> 即可从当前位置继续播放。</li><li>不传参数仅暂停，播放头保持现有位置不动。</li><li><code>suppressEvents=true</code> 适合静默跳转，避免 onUpdate 等回调不必要执行。</li><li>区分： <ul><li><code>.pause()</code>：暂停播放，保留当前播放位置；</li><li><code>.paused()</code>：读取/设置暂停状态的读写方法；</li><li><code>.addPause()</code>：在时间轴内预置暂停标记点，播放头走到该点自动暂停。</li></ul></li></ol></li></ol><h3 id="_4-2-24-paused" tabindex="-1"><a class="header-anchor" href="#_4-2-24-paused"><span>4.2.24 .paused()</span></a></h3><p><code>.paused()</code> 是 Timeline 实例方法，用于读取或设置时间轴的暂停状态。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 获取暂停状态</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">paused</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 设置暂停状态</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">paused</span><span class="token punctuation">(</span>value<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：传入布尔值修改暂停状态；不传参为读取当前暂停标记。和 <code>.pause()</code> / <code>.resume()</code> 功能同源，只是函数调用形式不同。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>value</code>【可选】：<code>boolean</code>，<code>true</code> 暂停，<code>false</code> 恢复播放。不传参数则读取状态。</li></ul></li><li>返回值：不传参返回布尔状态；传入参数返回当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">play</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">paused</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// false</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">paused</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 等价于 tl.pause()</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">paused</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// true</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">paused</span><span class="token punctuation">(</span><span class="token boolean">false</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 等价于 tl.resume()</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>读取的是暂停标记，<code>isActive()</code> 才用来判断动画是否被 ticker 追踪更新。</li><li>修改 <code>paused(false)</code> 会从当前播放头位置继续播放。</li><li>支持链式连续调用。</li><li>区分： <ul><li><code>.paused()</code>：读写暂停状态（getter/setter）；</li><li><code>.pause()</code>：方法，可附带跳转时间、suppressEvents 参数暂停；</li><li><code>.resume()</code>：仅恢复播放的简写方法。</li></ul></li></ol></li></ol><h3 id="_4-2-25-play" tabindex="-1"><a class="header-anchor" href="#_4-2-25-play"><span>4.2.25 .play()</span></a></h3><p><code>.play()</code> 是 Timeline 实例方法，从当前播放头位置开始播放时间轴。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">play</span><span class="token punctuation">(</span>fromTime<span class="token punctuation">,</span> suppressEvents<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：默认从当前播放位置继续播放；可指定跳转时间点后再播放，suppressEvents 控制跳转时是否屏蔽事件回调。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>fromTime</code>【可选】：<code>number | string</code>，跳转至该时间或者标签位置，之后开始播放。</li><li><code>suppressEvents</code>【可选】：<code>boolean</code>，默认值 <code>false</code>。<code>true</code> 跳转阶段不会触发 <code>onStart</code>、<code>onUpdate</code> 等事件。</li></ul></li><li>返回值：当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 从当前位置继续播放</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">play</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 跳转到标签 middle 位置，静默跳转后播放</span></span>
<span class="line"><span class="token comment">// tl.play(&quot;middle&quot;, true);</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>如果播放头已经在末尾，调用 <code>play()</code> 不会自动重播，需要使用 <code>.restart()</code>。</li><li>当时间轴处于暂停状态时，<code>play()</code> 等同于取消暂停继续运行。</li><li><code>suppressEvents</code> 适合程序驱动跳转，避免多余回调执行。</li><li>区分： <ul><li><code>.play()</code>：开始/继续播放，可附带跳转点位；</li><li><code>.restart()</code>：重置到起点并播放；</li><li><code>.resume()</code>：仅恢复播放，不能指定跳转时间。</li></ul></li></ol></li></ol><h3 id="_4-2-26-previouslabel" tabindex="-1"><a class="header-anchor" href="#_4-2-26-previouslabel"><span>4.2.26 .previousLabel()</span></a></h3><p><code>.previousLabel()</code> 是 Timeline 实例方法，获取播放头当前位置之前最近的标签名称。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">previousLabel</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：返回小于当前播放时间的最近标签；播放头在第一个标签之前，返回 <code>null</code>。</p></blockquote></li><li><p>属性说明</p><ul><li>参数：无</li><li>返回值：<code>string | null</code>，上一个临近标签名，不存在则返回 null。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">addLabel</span><span class="token punctuation">(</span><span class="token string">&quot;start&quot;</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">addLabel</span><span class="token punctuation">(</span><span class="token string">&quot;middle&quot;</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">addLabel</span><span class="token punctuation">(</span><span class="token string">&quot;end&quot;</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">seek</span><span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">previousLabel</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// &quot;middle&quot;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">seek</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">previousLabel</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// &quot;start&quot;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">seek</span><span class="token punctuation">(</span><span class="token operator">-</span><span class="token number">0.5</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">previousLabel</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// null</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="4"><li>使用要点</li><li>匹配规则：取<strong>小于当前播放头时间</strong>的最近标签。</li><li>不受播放方向影响，始终基于时间轴时间数值判断。</li><li>常用于实现“跳转到上一章节”交互。</li><li>区分： <ul><li><code>.previousLabel()</code>：播放头前面最近标签；</li><li><code>.currentLabel()</code>：播放头当前所在区间标签；</li><li><code>.nextLabel()</code>：播放头后面最近标签。</li></ul></li></ol></li></ol><h3 id="_4-2-27-progress" tabindex="-1"><a class="header-anchor" href="#_4-2-27-progress"><span>4.2.27 .progress()</span></a></h3><p><code>.progress()</code> 是 Timeline 实例方法，用于读取或设置时间轴的播放进度（0 ~ 1）。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 获取进度</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">progress</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 设置进度</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">progress</span><span class="token punctuation">(</span>value<span class="token punctuation">,</span> suppressEvents<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：<code>0</code> 代表时间轴起点，<code>1</code> 代表时间轴单次播放终点；进度是相对于单次 duration，不包含 delay。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>value</code>【可选】：<code>number</code>，取值范围 0~1。不传参数为读取；传入数值设置播放进度。</li><li><code>suppressEvents</code>【可选】：<code>boolean</code>，默认值 <code>false</code>。<code>true</code> 时跳转不触发 <code>onUpdate</code> 等事件回调。</li></ul></li><li>返回值：不传参返回进度数值；传入参数返回当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">progress</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 读取，默认 0</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">progress</span><span class="token punctuation">(</span><span class="token number">0.5</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 直接跳到50%进度</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">progress</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 0.5</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">progress</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 跳到终点，静默不触发事件</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>progress 只代表单次动画的完成比例，不受 repeat、repeatDelay 影响。</li><li>适合进度条、拖拽控制动画的交互场景。</li><li>设置 progress 不会自动播放，仅移动播放头位置。</li><li>区分： <ul><li><code>.progress()</code>：0~1 归一化播放比例；</li><li><code>.time()</code>：本地播放时间（单位秒）；</li><li><code>.totalProgress()</code>：包含 delay、repeat 的整体归一化进度。</li></ul></li></ol></li></ol><h3 id="_4-2-28-recent" tabindex="-1"><a class="header-anchor" href="#_4-2-28-recent"><span>4.2.28 .recent()</span></a></h3><p><code>.recent()</code> 是 Timeline 实例方法，获取<strong>最后添加</strong>的子项（Tween / Timeline / Callback），不受子项在时间轴上的时间位置影响。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">recent</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：按<strong>添加顺序</strong>取最新子项，不是按时间轴播放先后顺序；常用于接续上一个添加的动画来计算插入时间。</p></blockquote></li><li><p>属性说明</p><ul><li>参数：无</li><li>返回值：<code>Tween | Timeline | Callback</code>，最近添加的子动画实例</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 第1个添加的动画</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box1&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">100</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 第2个添加的动画，插入到时间0.5s位置</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box2&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">100</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token number">0.5</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 在box2动画结束后3秒添加新动画，利用recent拿到刚添加的box2</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box3&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">scale</span><span class="token operator">:</span><span class="token number">1.2</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span><span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> tl<span class="token punctuation">.</span><span class="token function">recent</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">endTime</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">+</span> <span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>只记录<strong>添加顺序</strong>，即使把动画插入到时间轴靠前位置，<code>recent()</code> 依然返回最后代码添加的子项。</li><li>可链式读取子项属性，例如 <code>tl.recent().endTime()</code> 获取上一个添加动画的结束时间。</li><li>时间轴为空时调用会返回 <code>undefined</code>。</li><li>区分： <ul><li><code>.recent()</code>：代码层面最后添加的子项；</li><li><code>.getChildren()</code>：获取所有直接子项数组，按时间顺序排列。</li></ul></li></ol></li></ol><h3 id="_4-2-29-remove" tabindex="-1"><a class="header-anchor" href="#_4-2-29-remove"><span>4.2.29 .remove()</span></a></h3><p><code>.remove()</code> 是 Timeline 实例方法，从当前时间轴移除指定子项（Tween / Timeline / Callback），子项本身不会被销毁。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">remove</span><span class="token punctuation">(</span>child<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：仅将子项从 timeline 的子列表剥离，不会执行 kill；移除后的动画实例可添加到其他时间轴复用。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>child</code>：<code>Tween | Timeline | Callback</code>，要移除的子动画实例</li></ul></li><li>返回值：当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> boxTween <span class="token operator">=</span> tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> subTl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">subTl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.circle&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">100</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span>subTl<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 将boxTween从时间轴中移除</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">remove</span><span class="token punctuation">(</span>boxTween<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>移除后子项仍然保留，只是不再属于该时间轴，可通过 <code>add()</code> 添加到别的 timeline。</li><li>若子项正在播放，移除后会立即脱离当前时间轴的时间控制。</li><li>仅支持传入子项实例，不能直接传选择器字符串。</li><li>区分： <ul><li><code>.remove()</code>：剥离子项，实例保留可复用；</li><li><code>.kill()</code>：销毁动画实例，释放资源，实例不可继续使用。</li></ul></li></ol></li></ol><h3 id="_4-2-30-removelabel" tabindex="-1"><a class="header-anchor" href="#_4-2-30-removelabel"><span>4.2.30 .removeLabel()</span></a></h3><p><code>.removeLabel()</code> 是 Timeline 实例方法，删除时间轴上指定名称的标签。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">removeLabel</span><span class="token punctuation">(</span>name<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：仅移除标签，不会删除时间轴上的动画子项；标签不存在时不会报错。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>name</code>：<code>string</code>，需要删除的标签名称</li></ul></li><li>返回值：当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">addLabel</span><span class="token punctuation">(</span><span class="token string">&quot;intro&quot;</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">addLabel</span><span class="token punctuation">(</span><span class="token string">&quot;outro&quot;</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 删除名为 outro 的标签</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">removeLabel</span><span class="token punctuation">(</span><span class="token string">&quot;outro&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>只移除标签记录，不会修改时间轴里任何补间、回调、子时间轴。</li><li>删除后，<code>tl.labels</code> 对象中将不再包含该标签。</li><li>若传入不存在的标签名，无任何操作，不会抛出异常。</li><li>区分： <ul><li><code>.removeLabel()</code>：删除单个指定标签；</li><li><code>.addLabel()</code>：在指定时间点新增标签。</li></ul></li></ol></li></ol><h3 id="_4-2-31-removepause" tabindex="-1"><a class="header-anchor" href="#_4-2-31-removepause"><span>4.2.31 .removePause()</span></a></h3><p><code>.removePause()</code> 是 Timeline 实例方法，移除通过 <code>.addPause()</code> 添加在时间轴指定点位的预置暂停标记。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">removePause</span><span class="token punctuation">(</span>position<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：仅移除预置暂停标记，不会删除该位置的动画；只对 <code>addPause()</code> 创建的暂停生效，不影响代码手动调用 <code>pause()</code>。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>position</code>：<code>number | string</code>，时间点（秒）或者标签名称，代表待移除暂停标记所在位置</li></ul></li><li>返回值：当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token comment">// 在1秒处添加预置暂停</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">addPause</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">opacity</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 删除1秒位置的预置暂停标记</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">removePause</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 也可以传入标签名移除暂停</span></span>
<span class="line"><span class="token comment">// tl.removePause(&quot;stage1&quot;);</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>必须传入添加暂停时对应的时间/标签，无法直接删除运行时手动触发的暂停。</li><li>移除后，播放头走到该点位将不再自动暂停，动画连续播放。</li><li>指定位置不存在暂停标记时，无操作、不报错。</li><li>区分： <ul><li><code>.removePause()</code>：删除时间轴上预置的 <code>addPause()</code> 暂停点；</li><li><code>.addPause()</code>：在时间轴某个时间点插入自动暂停标记；</li><li><code>.pause()</code>：代码手动暂停播放，不属于时间轴内置暂停标记。</li></ul></li></ol></li></ol><h3 id="_4-2-32-repeat" tabindex="-1"><a class="header-anchor" href="#_4-2-32-repeat"><span>4.2.32 .repeat()</span></a></h3><p><code>.repeat()</code> 是 Timeline 实例方法，用于读取或设置时间轴的重复播放次数。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 获取repeat值</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">repeat</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 设置repeat值</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">repeat</span><span class="token punctuation">(</span>value<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：repeat 代表完整循环次数；<code>0</code> 不重复，<code>-1</code> 代表无限循环。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>value</code>【可选】：<code>number</code>，循环次数。不传参数为读取；传入数值设置重复次数。</li></ul></li><li>返回值：不传参返回 repeat 数值；传入参数返回当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">repeat</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 完整播放2次重复，总共播放3轮</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">repeat</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">repeat</span><span class="token punctuation">(</span><span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 设置无限循环</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>repeat 计数是<strong>额外重复次数</strong>。repeat:2 → 播放 1(首次)+2(重复) = 3 轮动画。</li><li>设置 <code>-1</code> 会永久循环，需要手动调用 <code>pause()</code> / <code>kill()</code> 停止。</li><li>可在动画运行中动态修改 repeat 值，实时生效。</li><li>区分： <ul><li><code>.repeat()</code>：读写额外循环次数；</li><li><code>.repeatDelay()</code>：每次循环结束后等待的间隔时长；</li><li><code>.iteration()</code>：读写当前正在执行的循环索引。</li></ul></li></ol></li></ol><h3 id="_4-2-33-repeatdelay" tabindex="-1"><a class="header-anchor" href="#_4-2-33-repeatdelay"><span>4.2.33 .repeatDelay()</span></a></h3><p><code>.repeatDelay()</code> 是 Timeline 实例方法，用于读取或设置每次循环结束后，到下一轮循环开始前的等待时长（单位：秒）。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 获取 repeatDelay 值</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">repeatDelay</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 设置 repeatDelay 值</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">repeatDelay</span><span class="token punctuation">(</span>value<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：仅在开启 repeat 循环时生效；delay 是<strong>首次播放前</strong>等待，repeatDelay 是<strong>每轮循环之间</strong>等待。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>value</code>【可选】：<code>number</code>，间隔秒数。不传参数为读取；传入数值设置循环间隔。</li></ul></li><li>返回值：不传参返回 repeatDelay 数值；传入参数返回当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">repeat</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">repeatDelay</span><span class="token punctuation">(</span><span class="token number">1.5</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 每轮循环结束，等待1.5秒再开启下一轮</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">repeatDelay</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>不会作用于第一次播放，只在每一轮循环完成后生效。</li><li>可在动画运行期间动态修改，实时更新间隔。</li><li>若 <code>repeat:0</code>（不循环），repeatDelay 设置无效。</li><li>区分： <ul><li><code>.repeatDelay()</code>：循环与循环之间的等待时间；</li><li><code>.repeat()</code>：读写循环重复次数；</li><li><code>.delay()</code>：动画首次开始前的延迟。</li></ul></li></ol></li></ol><h3 id="_4-2-34-restart" tabindex="-1"><a class="header-anchor" href="#_4-2-34-restart"><span>4.2.34 .restart()</span></a></h3><p><code>.restart()</code> 是 Timeline 实例方法，将播放头重置到起点并开始播放。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">restart</span><span class="token punctuation">(</span>includeDelay<span class="token punctuation">,</span> suppressEvents<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：默认会跳过初始 delay；可通过参数控制是否启用初始延迟，suppressEvents 控制跳转阶段是否屏蔽事件回调。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>includeDelay</code>【可选】：<code>boolean</code>，默认值 <code>false</code>。<code>true</code> 代表重启时保留初始 delay 等待；<code>false</code> 直接立刻开始播放。</li><li><code>suppressEvents</code>【可选】：<code>boolean</code>，默认值 <code>false</code>。<code>true</code> 重置跳转过程不触发 <code>onStart</code>、<code>onUpdate</code> 等事件回调。</li></ul></li><li>返回值：当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">delay</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 重置到起点，直接播放，跳过初始delay</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">restart</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 重置并保留初始delay，静默跳转</span></span>
<span class="line"><span class="token comment">// tl.restart(true, true);</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>重启不会自动调用 <code>invalidate()</code>，元素属性缓存保留；如需重新采样DOM起始状态，要手动执行 <code>tl.invalidate()</code>。</li><li>会重置 <code>iteration()</code> 循环索引，回到第一轮。</li><li>无论动画当前是播放/暂停/播放完毕状态，都可以执行重启。</li><li>区分： <ul><li><code>.restart()</code>：回到起点 + 播放；</li><li><code>.play()</code>：从当前位置播放，不会重置播放头；</li><li><code>.seek(0)</code>：跳到起点，但不会自动播放。</li></ul></li></ol></li></ol><h3 id="_4-2-35-resume" tabindex="-1"><a class="header-anchor" href="#_4-2-35-resume"><span>4.2.35 .resume()</span></a></h3><p><code>.resume()</code> 是 Timeline 实例方法，恢复已暂停的时间轴，从当前播放头位置继续播放。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">resume</span><span class="token punctuation">(</span>suppressEvents<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：仅解除暂停状态，不能跳转播放位置；仅对处于暂停状态的时间轴生效。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>suppressEvents</code>【可选】：<code>boolean</code>，默认值 <code>false</code>。<code>true</code> 恢复播放时不触发 <code>onStart</code> 事件回调。</li></ul></li><li>返回值：当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">play</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">pause</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 从暂停位置继续播放</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">resume</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 静默恢复，不触发onStart</span></span>
<span class="line"><span class="token comment">// tl.resume(true);</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>如果时间轴本身未暂停，调用 <code>resume()</code> 无任何效果。</li><li>和 <code>play()</code> 不同，<code>resume()</code> 不支持传入时间点/标签来跳转位置。</li><li>不会重置播放头、循环索引。</li><li>区分： <ul><li><code>.resume()</code>：仅解除暂停，无跳转；</li><li><code>.play()</code>：可附带跳转点位然后播放；</li><li><code>.pause()</code>：暂停时间轴。</li></ul></li></ol></li></ol><h3 id="_4-2-36-reverse" tabindex="-1"><a class="header-anchor" href="#_4-2-36-reverse"><span>4.2.36 .reverse()</span></a></h3><p><code>.reverse()</code> 是 Timeline 实例方法，让时间轴反向播放，从当前播放头位置往起点方向运行。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">reverse</span><span class="token punctuation">(</span>fromTime<span class="token punctuation">,</span> suppressEvents<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：反向播放会将时间轴播放方向翻转；可可选指定跳转时间点后再反向播放，suppressEvents 控制跳转阶段是否屏蔽事件回调。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>fromTime</code>【可选】：<code>number | string</code>，跳转至该时间或者标签位置，之后开始反向播放。</li><li><code>suppressEvents</code>【可选】：<code>boolean</code>，默认值 <code>false</code>。<code>true</code> 跳转阶段不会触发 <code>onStart</code>、<code>onUpdate</code> 等事件。</li></ul></li><li>返回值：当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">play</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 从当前位置开始反向播放</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">reverse</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 跳转到标签 middle 位置，静默跳转后反向播放</span></span>
<span class="line"><span class="token comment">// tl.reverse(&quot;middle&quot;, true);</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>若播放头已经在起点位置，调用 <code>reverse()</code> 不会自动重播，需要使用 <code>.restart()</code>。</li><li>反向播放依然遵循 <code>timeScale</code>、<code>repeatDelay</code> 等配置。</li><li>当时间轴处于暂停状态时，<code>reverse()</code> 会开启反向播放。</li><li>区分： <ul><li><code>.reverse()</code>：开启反向播放，可附带跳转点位；</li><li><code>.reversed()</code>：读写时间轴的反向标记状态；</li><li><code>.play()</code>：正向播放。</li></ul></li></ol></li></ol><h3 id="_4-2-37-reversed" tabindex="-1"><a class="header-anchor" href="#_4-2-37-reversed"><span>4.2.37 .reversed()</span></a></h3><p><code>.reversed()</code> 是 Timeline 实例方法，用于读取或设置时间轴的<strong>反向播放标记状态</strong>。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 获取 reversed 状态</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">reversed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 设置 reversed 状态</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">reversed</span><span class="token punctuation">(</span>value<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：<code>true</code> 代表反向模式，<code>false</code> 代表正向模式；设置后不会自动播放，仅修改播放方向标记。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>value</code>【可选】：<code>boolean</code>。不传参数为读取状态；传入布尔值设置方向。</li></ul></li><li>返回值：不传参返回布尔状态；传入参数返回当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">play</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">reversed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// false，正向播放</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">reversed</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 切换为反向模式</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">reversed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// true</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>仅修改方向标记，不会自动开始播放；如需立刻反向播放，可配合 <code>.play()</code> 或者使用 <code>.reverse()</code>。</li><li>改变 reversed 不会移动当前播放头位置。</li><li>反向模式下，动画会从当前播放位置向时间起点推进。</li><li>区分： <ul><li><code>.reversed()</code>：读写方向状态（getter/setter）；</li><li><code>.reverse()</code>：方法，切换为反向并支持跳转点位。</li></ul></li></ol></li></ol><h3 id="_4-2-38-revert" tabindex="-1"><a class="header-anchor" href="#_4-2-38-revert"><span>4.2.38 .revert()</span></a></h3><p><code>.revert()</code> 是 Timeline 实例方法，将动画目标元素恢复到<strong>动画执行前原始状态</strong>，移除动画新增的行内样式，并销毁当前时间轴。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">revert</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：GSAP 3.11.0 新增；内部会执行 kill，执行后时间轴不可再播放；会清除动画添加的 inline style，区别于单纯 <code>progress(0)</code>。</p></blockquote></li><li><p>属性说明</p><ul><li>参数：无</li><li>返回值：当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">opacity</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 恢复元素原始状态，移除动画行内样式，销毁timeline</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">revert</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>恢复的是<strong>动画创建那一刻</strong>记录的DOM原始样式，并且删除由该动画新增的行内样式。</li><li>执行后时间轴被kill，<code>play()</code> / <code>seek()</code> 等方法不再可用。</li><li>适合组件销毁、动画卸载清理场景。</li><li>区分： <ul><li><code>.revert()</code>：还原DOM样式、移除inline样式、kill实例；</li><li><code>.kill()</code>：仅销毁动画，不会清理行内样式，元素保持动画结束时样式；</li><li><code>progress(0)</code>：回到起点数值，但保留行内样式，不会销毁实例。</li></ul></li></ol></li></ol><h3 id="_4-2-39-seek" tabindex="-1"><a class="header-anchor" href="#_4-2-39-seek"><span>4.2.39 .seek()</span></a></h3><p><code>.seek()</code> 是 Timeline 实例方法，将播放头直接跳转到指定的时间点/标签位置，<strong>不会自动播放</strong>。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">seek</span><span class="token punctuation">(</span>time<span class="token punctuation">,</span> suppressEvents<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：仅移动播放头，不改变暂停/播放状态；支持秒数或标签名作为目标位置。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>time</code>：<code>number | string</code>，目标时间（秒）或者标签名称。</li><li><code>suppressEvents</code>【可选】：<code>boolean</code>，默认值 <code>false</code>。<code>true</code> 跳转过程不触发 <code>onUpdate</code>、<code>onStart</code> 等事件回调。</li></ul></li><li>返回值：当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">addLabel</span><span class="token punctuation">(</span><span class="token string">&quot;mid&quot;</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 跳转到2秒位置</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">seek</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 跳转到标签 mid，静默跳转不触发事件</span></span>
<span class="line"><span class="token comment">// tl.seek(&quot;mid&quot;, true);</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li><code>seek()</code> 只是定位播放头，不会启动播放；如需跳转后自动播放，使用 <code>.play(time)</code>。</li><li>超出时间轴范围的值会被钳位到 0 ~ 总时长之间。</li><li>常用于拖拽进度条、点击标签跳转等交互场景。</li><li>区分： <ul><li><code>.seek()</code>：仅跳转播放头，不自动播放；</li><li><code>.play(fromTime)</code>：跳转 + 开始播放；</li><li><code>.progress()</code>：按 0~1 比例跳转播放头。</li></ul></li></ol></li></ol><h3 id="_4-2-40-set" tabindex="-1"><a class="header-anchor" href="#_4-2-40-set"><span>4.2.40 .set()</span></a></h3><p><code>.set()</code> 是 Timeline 实例方法，在时间轴指定位置设置目标属性，<strong>无过渡动画（瞬时生效）</strong>，本质是零时长补间。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">set</span><span class="token punctuation">(</span>target<span class="token punctuation">,</span> vars<span class="token punctuation">,</span> position<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：不产生动画过渡，直接设置样式/属性；可接收位置参数控制在时间轴的插入点位。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>target</code>：<code>string | object | array</code>，动画目标，DOM元素选择器、对象或数组。</li><li><code>vars</code>：<code>object</code>，要设置的属性集合。</li><li><code>position</code>【可选】：<code>number | string</code>，插入时间位置，支持数字、<code>&quot;+=1&quot;</code>、<code>&quot;-=1&quot;</code> 相对时间。</li></ul></li><li>返回值：当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 在时间0秒直接设置x与opacity，无动画</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">set</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">100</span><span class="token punctuation">,</span> <span class="token literal-property property">opacity</span><span class="token operator">:</span> <span class="token number">0.5</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 在2秒位置瞬时设置属性</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">set</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">scale</span><span class="token operator">:</span> <span class="token number">1.5</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 在上一个子项结束后0.5s设置</span></span>
<span class="line"><span class="token comment">// tl.set(&quot;.box&quot;, { rotation: 90 }, &quot;+=0.5&quot;);</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li><code>set</code> 是 duration=0 的 tween，不会产生插值过渡，属性瞬间生效。</li><li>常用于动画前置初始化状态、瞬间切换视觉状态。</li><li>位置参数规则和 <code>to()</code> / <code>from()</code> 完全一致。</li><li>区分： <ul><li><code>.set()</code>：瞬时设置属性，无动画；</li><li><code>.to()</code>：带过渡动画，从当前值变化到目标值；</li><li><code>.from()</code>：带过渡动画，从目标值变化到当前值。</li></ul></li></ol></li></ol><h3 id="_4-2-41-shiftchildren" tabindex="-1"><a class="header-anchor" href="#_4-2-41-shiftchildren"><span>4.2.41 .shiftChildren()</span></a></h3><p><code>.shiftChildren()</code> 是 Timeline 实例方法，批量移动时间轴内所有子项（Tween/Timeline）的起始时间，整体偏移。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">shiftChildren</span><span class="token punctuation">(</span>amount<span class="token punctuation">,</span> adjustLabels<span class="token punctuation">,</span> shiftLabels<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：批量平移全部子项的开始时间；可选择同步移动标签，常用于整体拉长/前移一段动画序列。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>amount</code>：<code>number</code>，偏移秒数。正数向后推迟，负数向前提前。</li><li><code>adjustLabels</code>【可选】：<code>boolean</code>，默认值 <code>false</code>。<code>true</code> 时，标签会跟随子项边界自动适配。</li><li><code>shiftLabels</code>【可选】：<code>boolean</code>，默认值 <code>false</code>。<code>true</code> 时所有标签一起偏移 <code>amount</code>。</li></ul></li><li>返回值：当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box1&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">100</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box2&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">100</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 所有子项整体向后推迟0.5秒，标签也一起偏移</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">shiftChildren</span><span class="token punctuation">(</span><span class="token number">0.5</span><span class="token punctuation">,</span> <span class="token boolean">false</span><span class="token punctuation">,</span> <span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>仅修改子项在时间轴上的<strong>起始时间</strong>，不会修改子项本身时长。</li><li>负数偏移会把子项往前挪，注意不要让子项起始时间小于0。</li><li>仅作用于直接子项，嵌套子Timeline内部的子元素不会单独偏移。</li><li>区分： <ul><li><code>.shiftChildren()</code>：批量平移全部直接子项；</li><li>单独修改单个子项 <code>startTime()</code>：只移动某一个子动画。</li></ul></li></ol></li></ol><h3 id="_4-2-42-starttime" tabindex="-1"><a class="header-anchor" href="#_4-2-42-starttime"><span>4.2.42 .startTime()</span></a></h3><p><code>.startTime()</code> 是 Timeline 实例方法，用于读取或设置该时间轴在<strong>父级时间轴内的开始时间</strong>。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 获取 startTime</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">startTime</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 设置 startTime</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">startTime</span><span class="token punctuation">(</span>value<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：如果该 Timeline 是根时间轴（没有父级），startTime 固定为0；修改它只会改变它在父Timeline中的排布位置，不会修改内部子项相对时间。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>value</code>【可选】：<code>number</code>，时间秒数。不传参数为读取；传入数值设置开始时间。</li></ul></li><li>返回值：不传参返回时间数值；传入参数返回当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> parentTl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> childTl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">childTl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">parentTl<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span>childTl<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>childTl<span class="token punctuation">.</span><span class="token function">startTime</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 0</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 将子时间轴在父级中延后1.5秒开始</span></span>
<span class="line">childTl<span class="token punctuation">.</span><span class="token function">startTime</span><span class="token punctuation">(</span><span class="token number">1.5</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li><code>startTime</code> 是<strong>相对于父容器</strong>的时间，不是子Timeline内部的本地时间。</li><li>修改后仅移动这个timeline整体，内部所有子动画之间的相对时序保持不变。</li><li>根Timeline不存在父级，设置 startTime 无效。</li><li>区分： <ul><li><code>.startTime()</code>：当前实例在父时间轴的起始位置；</li><li><code>.duration()</code>：当前时间轴自身总时长；</li><li><code>.shiftChildren()</code>：移动当前timeline<strong>内部</strong>所有子项。</li></ul></li></ol></li></ol><h3 id="_4-2-43-then" tabindex="-1"><a class="header-anchor" href="#_4-2-43-then"><span>4.2.43 .then()</span></a></h3><p><code>.then()</code> 是 Timeline 实例方法，返回 Promise，在时间轴<strong>正常完成</strong>时触发回调，支持异步 await。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span>onFulfilled<span class="token punctuation">,</span> onRejected<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：GSAP Timeline 实现了 Promise 接口；当动画被 <code>kill()</code> / <code>revert()</code> 中断时 Promise 会 reject；循环动画（repeat:-1）永远不会 resolve。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>onFulfilled</code>【可选】：<code>Function</code>，动画正常播放完成后的回调函数。</li><li><code>onRejected</code>【可选】：<code>Function</code>，动画被中断、kill 时的拒绝回调函数。</li></ul></li><li>返回值：<code>Promise</code> 对象</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">opacity</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;timeline 播放完成&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">catch</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">err</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;动画被中断&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 也可配合 await</span></span>
<span class="line"><span class="token comment">// await tl;</span></span>
<span class="line"><span class="token comment">// console.log(&quot;播放结束&quot;);</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>当设置 <code>repeat &gt; 0</code>，会在<strong>所有循环全部结束</strong>后才 resolve。</li><li>反向播放（reversed）播放到起点也视为完成，触发 resolve。</li><li><code>seek()</code>、<code>pause()</code> 单纯暂停跳转<strong>不会</strong>触发 reject；只有 <code>kill()</code> / <code>revert()</code> 才会 reject promise。</li><li>区分： <ul><li><code>.then()</code>：Promise 风格，用于异步等待动画完成；</li><li><code>onComplete</code>：timeline 配置里的回调选项，属于同步回调；</li><li><code>.catch()</code>：捕获动画中断 reject 场景。</li></ul></li></ol></li></ol><h3 id="_4-2-44-time" tabindex="-1"><a class="header-anchor" href="#_4-2-44-time"><span>4.2.44 .time()</span></a></h3><p><code>.time()</code> 是 Timeline 实例方法，用于读取或设置时间轴<strong>本地当前播放时间（单位秒）</strong>。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 获取当前本地时间</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">time</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 设置本地时间</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">time</span><span class="token punctuation">(</span>value<span class="token punctuation">,</span> suppressEvents<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：代表时间轴内部本地时间，不受 <code>timeScale</code> 影响；区别于 <code>totalTime()</code>。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>value</code>【可选】：<code>number</code>，目标本地时间（秒）。不传参数为读取；传入数值设置播放时间。</li><li><code>suppressEvents</code>【可选】：<code>boolean</code>，默认值 <code>false</code>。<code>true</code> 跳转过程不触发 <code>onUpdate</code>、<code>onStart</code> 等事件回调。</li></ul></li><li>返回值：不传参返回时间数值；传入参数返回当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">opacity</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">time</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 读取当前本地时间</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">time</span><span class="token punctuation">(</span><span class="token number">1.2</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 设置本地播放时间到1.2秒</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 静默跳转，不触发事件</span></span>
<span class="line"><span class="token comment">// tl.time(0.5, true);</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li><code>time()</code> 只看单次动画的本地时间，不包含 <code>repeatDelay</code> 和重复循环的累计时长。</li><li>修改 <code>time()</code> 会直接移动播放头，行为类似 <code>seek()</code>。</li><li>超出 <code>duration()</code> 的值会被钳位到 <code>0 ~ duration</code>。</li><li>区分： <ul><li><code>.time()</code>：单次动画本地时间，不含循环与repeatDelay；</li><li><code>.totalTime()</code>：包含循环、repeatDelay 的完整总时间；</li><li><code>.progress()</code>：0~1归一化进度。</li></ul></li></ol></li></ol><h3 id="_4-2-45-timescale" tabindex="-1"><a class="header-anchor" href="#_4-2-45-timescale"><span>4.2.45 .timeScale()</span></a></h3><p><code>.timeScale()</code> 是 Timeline 实例方法，用于读取或设置时间轴的播放速率。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 获取 timeScale 值</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">timeScale</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 设置 timeScale 值</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">timeScale</span><span class="token punctuation">(</span>value<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：<code>1</code> 为正常速度；大于1加速，小于1减速；可动态修改，实时生效。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>value</code>【可选】：<code>number</code>，播放倍率。不传参数为读取；传入数值设置播放速度。</li></ul></li><li>返回值：不传参返回倍率数值；传入参数返回当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">opacity</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">timeScale</span><span class="token punctuation">(</span><span class="token number">0.5</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 减速，0.5倍速</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">timeScale</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">timeScale</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 加速，2倍速</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>倍率会递归作用于内部所有子Tween、子Timeline。</li><li>不会改变 <code>duration()</code> 数值，只改变实际播放耗时。</li><li>支持动态在动画运行中修改，立刻生效。</li><li>区分： <ul><li><code>.timeScale()</code>：修改播放速度；</li><li><code>.time()</code>：读写本地播放时间；</li><li><code>.seek()</code>：跳转播放头位置，不改变速率。</li></ul></li></ol></li></ol><h3 id="_4-2-46-to" tabindex="-1"><a class="header-anchor" href="#_4-2-46-to"><span>4.2.46 .to()</span></a></h3><p><code>.to()</code> 是 Timeline 实例方法，向时间轴添加一个<strong>正向过渡补间</strong>，从目标当前属性值动画变化到设置的目标属性。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span>target<span class="token punctuation">,</span> vars<span class="token punctuation">,</span> position<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：最常用的动画方法；自动读取元素当前状态作为动画起始值，过渡到vars里定义的目标值。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>target</code>：<code>string | object | array</code>，动画目标，DOM选择器、对象或对象数组。</li><li><code>vars</code>：<code>object</code>，动画配置对象，包含目标属性、duration、ease等。</li><li><code>position</code>【可选】：<code>number | string</code>，插入位置，支持绝对秒数、<code>&quot;+=n&quot;</code>/<code>&quot;-=n&quot;</code>相对时间。</li></ul></li><li>返回值：当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 从当前位置移动到x:200，时长1秒</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 在上一个动画结束后额外延迟0.5s再执行</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">opacity</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token string">&quot;+=0.5&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>自动采集动画执行瞬间目标的初始属性，无需手动写起始值。</li><li><code>position</code> 相对时间语法：<code>&quot;+=1&quot;</code> 在上一个子项结束后等待1s；<code>&quot;-=1&quot;</code> 和上一个子项重叠1s。</li><li>vars内可配置ease、delay、onComplete等补间参数。</li><li>区分： <ul><li><code>.to()</code>：当前值 → 目标值</li><li><code>.from()</code>：目标值 → 当前值</li><li><code>.fromTo()</code>：自定义起始值与结束值</li></ul></li></ol></li></ol><h3 id="_4-2-47-totalduration" tabindex="-1"><a class="header-anchor" href="#_4-2-47-totalduration"><span>4.2.47 .totalDuration()</span></a></h3><p><code>.totalDuration()</code> 是 Timeline 实例方法，用于读取或设置包含循环、repeatDelay在内的<strong>完整总时长（单位秒）</strong>。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 获取 totalDuration</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">totalDuration</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 设置 totalDuration</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">totalDuration</span><span class="token punctuation">(</span>value<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：<code>duration()</code> 是单次播放时长；<code>totalDuration()</code> 会把 repeat、repeatDelay 全部纳入计算。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>value</code>【可选】：<code>number</code>，目标总时长。不传参数为读取；传入数值会自动缩放 timeScale 来匹配目标总时长。</li></ul></li><li>返回值：不传参返回时长数值；传入参数返回当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">opacity</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">repeat</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">repeatDelay</span><span class="token punctuation">(</span><span class="token number">0.5</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">duration</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 单次时长 2</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">totalDuration</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 2 + (2 + 0.5)*2 = 7</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">totalDuration</span><span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 自动调整timeScale，让完整总时长等于10秒</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>计算公式：<code>totalDuration = duration + (duration + repeatDelay) * repeat</code>。</li><li>当 <code>repeat:-1</code>（无限循环），<code>totalDuration()</code> 返回 <code>Infinity</code>。</li><li>赋值修改 totalDuration 不会改变内部子项时序，只会修改 <code>timeScale</code> 整体缩放播放速度。</li><li>区分： <ul><li><code>.totalDuration()</code>：包含repeat、repeatDelay 的全部总时长；</li><li><code>.duration()</code>：单次一轮动画的基础时长，不包含循环；</li><li><code>.totalTime()</code>：当前播放头对应的累计总时间。</li></ul></li></ol></li></ol><h3 id="_4-2-48-totalprogress" tabindex="-1"><a class="header-anchor" href="#_4-2-48-totalprogress"><span>4.2.48 .totalProgress()</span></a></h3><p><code>.totalProgress()</code> 是 Timeline 实例方法，用于读取或设置<strong>包含所有循环、repeatDelay 的整体归一化进度</strong>，取值范围 <code>0 ~ 1</code>。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 获取 totalProgress</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">totalProgress</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 设置 totalProgress</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">totalProgress</span><span class="token punctuation">(</span>value<span class="token punctuation">,</span> suppressEvents<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：<code>totalProgress</code> 对应 <code>totalDuration</code> 的进度；而 <code>progress</code> 仅为单次一轮动画的进度。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>value</code>【可选】：<code>number</code>，进度值（0~1）。不传参数为读取；传入数值跳转播放头。</li><li><code>suppressEvents</code>【可选】：<code>boolean</code>，默认值 <code>false</code>。<code>true</code> 跳转过程不触发 <code>onUpdate</code>、<code>onStart</code> 等事件回调。</li></ul></li><li>返回值：不传参返回进度数值；传入参数返回当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">opacity</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">repeat</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">repeatDelay</span><span class="token punctuation">(</span><span class="token number">0.5</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">totalProgress</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">totalProgress</span><span class="token punctuation">(</span><span class="token number">0.5</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 跳转到全部完整动画的50%位置</span></span>
<span class="line"><span class="token comment">// tl.totalProgress(0.5, true); // 静默跳转</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>进度 <code>0</code> 代表整个完整动画起点，<code>1</code> 代表全部循环+repeatDelay 播放完毕。</li><li>支持超出0~1范围赋值，数值会自动钳位。</li><li>无限循环 <code>repeat:-1</code> 时，<code>totalProgress</code> 不可用，因为 <code>totalDuration</code> 为无穷大。</li><li>区分： <ul><li><code>.totalProgress()</code>：包含循环、repeatDelay 的全局总进度；</li><li><code>.progress()</code>：仅当前单轮动画的进度；</li><li><code>.totalTime()</code>：对应的总时间（秒）而非0~1比例。</li></ul></li></ol></li></ol><h3 id="_4-2-49-totaltime" tabindex="-1"><a class="header-anchor" href="#_4-2-49-totaltime"><span>4.2.49 .totalTime()</span></a></h3><p><code>.totalTime()</code> 是 Timeline 实例方法，用于读取或设置包含循环、repeatDelay 的<strong>累计总播放时间（单位秒）</strong>。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 获取 totalTime</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">totalTime</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 设置 totalTime</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">totalTime</span><span class="token punctuation">(</span>value<span class="token punctuation">,</span> suppressEvents<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：<code>totalTime</code> 是包含所有循环与循环间隔的全局时间；<code>time()</code> 仅代表单轮内本地时间。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>value</code>【可选】：<code>number</code>，目标累计总时间（秒）。不传参数为读取；传入数值跳转播放头。</li><li><code>suppressEvents</code>【可选】：<code>boolean</code>，默认值 <code>false</code>。<code>true</code> 跳转过程不触发 <code>onUpdate</code>、<code>onStart</code> 等事件回调。</li></ul></li><li>返回值：不传参返回时间数值；传入参数返回当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">opacity</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">repeat</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">repeatDelay</span><span class="token punctuation">(</span><span class="token number">0.5</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">totalTime</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">totalTime</span><span class="token punctuation">(</span><span class="token number">2.5</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 跳转到全局总时间2.5秒位置</span></span>
<span class="line"><span class="token comment">// tl.totalTime(2.5, true); // 静默跳转，不触发回调事件</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>当动画多次循环，<code>totalTime</code> 会叠加每一轮动画时长和 <code>repeatDelay</code>。</li><li>赋值会直接定位播放头到全局时间点，超出 <code>totalDuration</code> 的值会被钳位。</li><li>无限循环 <code>repeat:-1</code> 时，<code>totalTime</code> 可以持续无限增长。</li><li>区分： <ul><li><code>.totalTime()</code>：包含循环、repeatDelay 的全局累计时间；</li><li><code>.time()</code>：仅当前单轮动画内部本地时间；</li><li><code>.totalProgress()</code>：总时间对应的0~1归一化进度。</li></ul></li></ol></li></ol><h3 id="_4-2-50-tweenfromto" tabindex="-1"><a class="header-anchor" href="#_4-2-50-tweenfromto"><span>4.2.50 .tweenFromTo()</span></a></h3><p><code>.tweenFromTo()</code> 是 Timeline 实例方法，创建一个临时补间，<strong>在当前时间轴内从一个时间点平滑动画到另一个时间点</strong>，常用于 scrub 时间轴播放头。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">tweenFromTo</span><span class="token punctuation">(</span>fromTime<span class="token punctuation">,</span> toTime<span class="token punctuation">,</span> vars<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：返回一个 Tween 实例；fromTime / toTime 支持数字（秒）或标签名；用来平滑驱动时间轴播放头在两个点位之间移动。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>fromTime</code>：<code>number | string</code>，起始位置，秒数或标签名称。</li><li><code>toTime</code>：<code>number | string</code>，结束位置，秒数或标签名称。</li><li><code>vars</code>【可选】：<code>object</code>，补间配置（duration、ease、onUpdate 等）。</li></ul></li><li>返回值：Tween 实例</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">addLabel</span><span class="token punctuation">(</span><span class="token string">&quot;start&quot;</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">addLabel</span><span class="token punctuation">(</span><span class="token string">&quot;end&quot;</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 从标签start平滑过渡到end，时长1秒</span></span>
<span class="line"><span class="token keyword">const</span> scrubTween <span class="token operator">=</span> tl<span class="token punctuation">.</span><span class="token function">tweenFromTo</span><span class="token punctuation">(</span><span class="token string">&quot;start&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;end&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token literal-property property">ease</span><span class="token operator">:</span> <span class="token string">&quot;power2.inOut&quot;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>本质是生成一个独立补间，在执行过程中持续修改 timeline 的 <code>time</code>。</li><li><code>fromTime</code> 大于 <code>toTime</code> 时，会反向移动播放头。</li><li>此补间和 timeline 相互独立，kill 原 timeline 不会自动 kill 这个 tween。</li><li>区分： <ul><li><code>.tweenFromTo()</code>：生成补间，平滑驱动播放头在两点间滑动；</li><li><code>.seek()</code>：直接瞬间跳转播放头，无过渡动画；</li><li><code>.tweenTo()</code>：只指定终点，从当前播放头位置平滑过渡到目标点。</li></ul></li></ol></li></ol><h3 id="_4-2-51-tweento" tabindex="-1"><a class="header-anchor" href="#_4-2-51-tweento"><span>4.2.51 .tweenTo()</span></a></h3><p><code>.tweenTo()</code> 是 Timeline 实例方法，创建临时补间，<strong>从当前播放头位置平滑动画到目标时间点/标签</strong>，常用于拖拽、滚动驱动播放头。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">tl<span class="token punctuation">.</span><span class="token function">tweenTo</span><span class="token punctuation">(</span>toTime<span class="token punctuation">,</span> vars<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>提示：返回 Tween 实例；toTime 支持秒数或标签名；只需要传入终点，起点自动取 timeline 当前播放位置。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>toTime</code>：<code>number | string</code>，目标位置，秒数或标签名称。</li><li><code>vars</code>【可选】：<code>object</code>，补间配置（duration、ease、onUpdate 等）。</li></ul></li><li>返回值：Tween 实例</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">addLabel</span><span class="token punctuation">(</span><span class="token string">&quot;mid&quot;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">addLabel</span><span class="token punctuation">(</span><span class="token string">&quot;end&quot;</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 从当前播放位置平滑过渡到标签mid，时长0.8秒</span></span>
<span class="line"><span class="token keyword">const</span> scrubTween <span class="token operator">=</span> tl<span class="token punctuation">.</span><span class="token function">tweenTo</span><span class="token punctuation">(</span><span class="token string">&quot;mid&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">0.8</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token literal-property property">ease</span><span class="token operator">:</span> <span class="token string">&quot;power3.out&quot;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>生成独立Tween，运行期间持续更新 timeline 的 <code>time</code>。</li><li>目标位置小于当前播放头时，自动反向滑动播放头。</li><li>该补间独立于原timeline，kill timeline 不会自动销毁这个tween。</li><li>区分： <ul><li><code>.tweenTo()</code>：起点为当前播放头，平滑移动到目标点位</li><li><code>.tweenFromTo()</code>：手动指定起点与终点，两点之间平滑过渡</li><li><code>.seek()</code>：瞬时跳转播放头，没有过渡动画</li></ul></li></ol></li></ol><h3 id="_4-2-52-yoyo" tabindex="-1"><a class="header-anchor" href="#_4-2-52-yoyo"><span>4.2.52 .yoyo()</span></a></h3><p><code>.yoyo()</code> 是 Timeline 实例方法，用于读取或设置 yoyo 开关；开启后，每一轮循环播放完成后会<strong>反向回放</strong>，往复运动。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 获取 yoyo 值</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">yoyo</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 设置 yoyo 值</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">yoyo</span><span class="token punctuation">(</span>value<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：仅在 <code>repeat &gt; 0</code> 时生效；yoyo 不改变总时长，只改变循环播放方向。</p></blockquote></li><li><p>属性说明</p><ul><li>参数： <ul><li><code>value</code>【可选】：<code>boolean</code>。不传参数为读取；传入布尔值开启/关闭yoyo。</li></ul></li><li>返回值：不传参返回布尔值；传入参数返回当前 Timeline 实例，支持链式调用。</li></ul></li><li><p>示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> tl <span class="token operator">=</span> gsap<span class="token punctuation">.</span><span class="token function">timeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string">&quot;.box&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">repeat</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">tl<span class="token punctuation">.</span><span class="token function">yoyo</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 开启往复，正向→反向→正向</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>tl<span class="token punctuation">.</span><span class="token function">yoyo</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用要点</p><ol><li>yoyo 只影响循环的下一轮播放方向，首轮永远正向播放。</li><li>开启 yoyo 后，<code>repeat</code> 计数依然代表额外重复次数。<code>repeat:2, yoyo:true</code>：正向 → 反向 → 正向。</li><li>可在动画运行中动态修改，实时生效。</li><li>区分： <ul><li><code>.yoyo()</code>：控制循环是否折返反向播放；</li><li><code>.repeat()</code>：设置循环重复次数；</li><li><code>.reversed()</code>：全局固定播放方向，和循环yoyo无关。</li></ul></li></ol></li></ol>`,182)])])}const i=s(t,[["render",l]]),u=JSON.parse('{"path":"/animation/framework/gasp/04.html","title":"四、时间线-Timeline","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1790564252000,"contributors":[{"name":"zhao-farmer","username":"zhao-farmer","email":"857899180@qq.com","commits":1,"url":"https://github.com/zhao-farmer"}],"changelog":[{"hash":"cfbbc7f726ec8e4db66fff0788f0c77d25bef9b8","time":1790564252000,"email":"857899180@qq.com","author":"zhao-farmer","message":"前端代码记录"}]},"filePathRelative":"animation/framework/gasp/04.md"}');export{i as comp,u as data};
